SELECT 'c8595d07-96b6-5ed1-a056-c63a2d3d91d7'::uuid,'بودكاست كرتون كرتون','بودكاست عربي أسبوعي عن الرسوم المتحركة والأنيميشن وصناعة المحتوى المرئي، يقدمه عبدالله رافعة وعمار صبان.','عبدالله رافعة وعمار صبان','عبدالله رافعة وعمار صبان يقدمان بودكاست كرتون كرتون، أحد أشهر البودكاستات العربية المتخصصة في الرسوم المتحركة وصناعة الأنيميشن.','f26712fa-c904-43be-9f2a-a3f0f4860dd6'::uuid,'cultural','https://media.podeo.co/podcasts/ODQwMw/image.jpg?ivc=1746479144','beginner',(SELECT id FROM hosts WHERE name_ar='عبدالله رافعة وعمار صبان' LIMIT 1),0,0,NOW()
