SELECT 'b83d1b19-4fb3-5b4e-adf6-c064fbd4d255'::uuid,'ديوان','بودكاست حواري ثقافي وفكري يقدمه عبدالمجيد الكناني، يستكشف الأفكار والتحولات الثقافية والاجتماعية في المنطقة العربية.','عبدالمجيد الكناني','عبدالمجيد الكناني كاتب ومقدّم سعودي، يقدم بودكاست ديوان في حوارات ثقافية وفكرية مع ضيوف من مجالات مختلفة.','f26712fa-c904-43be-9f2a-a3f0f4860dd6'::uuid,'cultural','https://image.simplecastcdn.com/images/5d56b6a7-6c0e-4c1e-bf71-1b03d85774fb/6416e907-1d69-43ed-a1af-ed785cf89399/3000x3000/3000.jpg?aid=rss_feed','beginner',(SELECT id FROM hosts WHERE name_ar='عبدالمجيد الكناني' LIMIT 1),0,0,NOW()
