INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل نسينا كيف نفكر؟.. عقل الأمة في عصر التكنولوجيا مع إبراهيم التميمي | بودكاست ديوان','ثورة التكنولوجيا، تسارع الأحداث، وعقود من التحولات الفكرية.. كيف وجد العقل العربي نفسه أمام تحديات العصر الرقمي؟ وهل ما نعيشه اليوم من استهلاك تقني هو انعكاس لأزمات أعمق في الوعي والإدارة؟ في هذه الحلقة، نفتح نافذة مختلفة كلياً لقراءة فكر المفكر البحريني الراحل الدكتور محمد جابر الأنصاري عبر بودكاست ديوان ، برفقة الضيف إبراهيم التميمي. نتأمل بعمق في مصطلحات مثل "البداوة المقنعة"، ونفكك خبايا العلاقة الشائكة بين تبني التكنولوجيا الحديثة وغياب القدرة على إنتاجها. نغوص في كواليس تحول مفهوم البطولة من فرسان التاريخ إلى أزرار التقنية وخوارزميات الذكاء الاصطناعي، ونناقش أزمة الإدارة والتخطيط وغياب الوعي النقدي في عالمنا العربي لصالح ثقافة الشعارات والتغريدات العابرة. محاور الحلقة: • هل نسينا كيف نفكر؟ قراءة جريئة في أزمة الوعي والعقل العربي. • من صراع الفرسان إلى أزرار التكنولوجيا: كيف تحولت معارك العصر؟ • أزمة إدارية أم أزمة وعي؟ لماذا تفوقت أدوات التلقي على ثقافة الإنتاج؟ • تكامل المؤسسات: كيف نصنع جيلاً واعياً بين الأسرة، التعليم، والإعلام؟ 📌 آراء الضيوف لا تعبّر بالضرورة عن رأي القناة 📅 ','https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/a4ef6006-fb7f-486e-bfe3-7a864badbb96/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=a4ef6006-fb7f-486e-bfe3-7a864badbb96&amp;feed=lhwIWvSy',3350,'2026-11-08T10:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='ديوان' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/a4ef6006-fb7f-486e-bfe3-7a864badbb96/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=a4ef6006-fb7f-486e-bfe3-7a864badbb96&amp;feed=lhwIWvSy');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'شانزليزيه الخليج: أين ذهبت ملامح المنامة القديمة؟ مع إبراهيم بشمي | بودكاست ديوان','في هذه الحلقة الممتعة، يطوف بنا الأديب والصحفي البحريني الأستاذ إبراهيم بشمي في رحلة دافئة عبر ذاكرة المنامة القديمة وأيامها كـ "شانزليزيه الخليج". يستعرض الحوار ملامح التعايش الفريد والتعددية العرقية والثقافية في أسواق المنامة وعائلاتها، إلى جانب استذكار دور المجلات والثقافة القادمة من القاهرة وبيروت، وتطور الصحافة والفكر في البحرين استناداً إلى رؤى المفكر الراحل الدكتور محمد جابر الأنصاري أبرز محاور الحلقة: • ذاكرة المنامة وتنوعها: استذكار تفاصيل الأسواق العريقة (كسوق الطواويش وباب البحرين) وحالة التعايش والتسامح الفريدة بين مختلف الهويات والعروق والديانات. • المشهد الثقافي والصحفي القديم: دور مكتبة عبيد والمجلات القادمة من القاهرة وبيروت وبغداد في تغذية الوعي الثقافي للجيل السابق. • إرث الدكتور محمد جابر الأنصاري: مناقشة أفكاره حول التعددية، والهوية الوطنية، وضرورة عدم إقصاء الآخر. • تطور الصحافة: بحث واقع الصحافة البحرينية بين الأمس واليوم، وتحديات تحرر الصحف من القوالب التقليدية لتلبية تطلعات الجيل الجديد. 📌 آراء الضيوف لا تعبّر بالضرورة عن رأي القناة 📅 كل إسبوعين يوم الأحد على قن','https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/8beb352d-986c-4e74-a231-39fb6cc35f21/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=8beb352d-986c-4e74-a231-39fb6cc35f21&amp;feed=lhwIWvSy',5111,'2026-10-18T08:05:02Z'::timestamptz,0 FROM podcasts p WHERE p.title='ديوان' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/8beb352d-986c-4e74-a231-39fb6cc35f21/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=8beb352d-986c-4e74-a231-39fb6cc35f21&amp;feed=lhwIWvSy');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'إلى أين تتجه العلاقة الخليجية الإيرانية؟ مع حسن المصطفى| بودكاست ديوان','عقود من التوتر، سباق النفوذ، وتاريخ حافل بالمحطات المفصلية.. كيف تشكلت التعقيدات بين الخليج وإيران؟ وهل ما نعيشه اليوم هو امتداد لجذور قديمة لم تتغير؟ في هذه الحلقة، نفتح ملف العلاقة الخليجية الإيرانية مع الباحث والخبير في شؤون الشرق الأوسط الأستاذ حسن المصطفى، لنفكك الشفرات التاريخية والسياسية لهذا الجوار الشائك. نعود إلى قراءة متعمقة في فكر المفكر الدكتور محمد جابر الأنصاري، ونحلل كيف تحركت إيران عبر حقبها المختلفة من الشاه إلى الثورة. نبحث في كواليس أحداث فارقة مثل احتلال الجزر الإماراتية الثلاث، ونناقش موازين القوة، ووجهة نظر الأنصاري الجريئة في نقد الذات والوعي السياسي العربي بين الأمس واليوم. محاور الحلقة: • ما الذي يحكم السلوك الإيراني تجاه الخليج عبر التاريخ؟ • قراءة مختلفة لقضية الجزر الثلاث ورود الفعل العربية. • نقد الذات والوعي السياسي: هل استشرق الأنصاري واقعنا اليوم؟ • أبعاد الجوار الإقليمي إلى أين تشير الموازين اليوم؟ 📌 آراء الضيوف لا تعبّر بالضرورة عن رأي القناة 📅 كل إسبوعين يوم الأحد على قناة حكاية في يوتيوب وجميع منصات البودكاست برعاية: 🧠📖 دارة محمد جابر الأنصاري للفكر','https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/cd0c2485-8753-4625-84d8-b696d8a9639a/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=cd0c2485-8753-4625-84d8-b696d8a9639a&amp;feed=lhwIWvSy',5629,'2026-10-04T08:01:38Z'::timestamptz,0 FROM podcasts p WHERE p.title='ديوان' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/cd0c2485-8753-4625-84d8-b696d8a9639a/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=cd0c2485-8753-4625-84d8-b696d8a9639a&amp;feed=lhwIWvSy');
