SELECT p.id,'لماذا نخشى الفلسفة ونقدس التاريخ؟! مع د.حسن مدن | بودكاست ديوان','في هذه الحلقة من بودكاست ديوان، نغوص في مواجهة فكرية صريحة تفكك السائد وتطرح السؤال الأكثر إلحاحاً: لماذا نخشى الفلسفة ونقدّس تاريخنا؟ نطرح التساؤل المباشر حول آليات عمل العقل العربي، وكيف يتحول الموروث من درس إلى قيد يمنعنا من قراءة الحاضر بعيون نقدية وواعية. يحل الكاتب والمفكر د. حسن مدن ضيفاً ليقرأ معنا واقع الوعي والثقافة، مستدعياً طروحاته حول ضرورة التفكير الحر ومواجهة الانحيازات، ليخوض نقاشاً يفكك معادلة الهوية الوطنية في مواجهة الطائفية والجهوية، ويحدد بدقة أين تقف أسئلة التنوير اليوم. محاور الحلقة: • فوبيا السؤال والتفكير النقدي: المعادلة الصعبة بين الخوف من الفلسفة والاستسلام للمسلمات الموروثة. • تقديس الماضي وشجاعة النقد: كيف تحول التاريخ من مدرسة للتعلم إلى عرش مقدس يهرب إليه العقل من أسئلة الحاضر؟ • تفكيك الهويات الضيقة: البنية التحتية للوعي الوطني؛ كيف تنخر الانقسامات الفئوية في جسد الدولة؟ • الرهان على المستقبل: كيف ينقذ التفكير الحر الجيل الجديد من مساحيق التجميل الفكري وضجيج العصر؟ 📌 آراء الضيوف لا تعبّر بالضرورة عن رأي القناة 📅 كل إسبوعين يوم الأحد على قناة حكاية في يو','https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/85fb2070-2425-49c2-9f26-ecb48603970b/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=85fb2070-2425-49c2-9f26-ecb48603970b&amp;feed=lhwIWvSy',4392,'2026-09-13T06:16:15Z'::timestamptz,0 FROM podcasts p WHERE p.title='ديوان' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/85fb2070-2425-49c2-9f26-ecb48603970b/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=85fb2070-2425-49c2-9f26-ecb48603970b&amp;feed=lhwIWvSy');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'السلطة الرابعة تحت المجهر مع سليمان جودة','في هذه الحلقة من بودكاست ديوان، نغوص في مواجهة صحفية وحوارية مكشوفة تُظهر واقع الإعلام وصناعة الوعي العربي دون تجميل، لنطرح التساؤل المباشر: كيف تحولت "السلطة الرابعة" من قائد للمجتمع إلى ساحة محاصرة بين قبضة السلطة وعبثية الترند؟ يحل الكاتب الصحفي سليمان جودة ضيفاً ليقرأ معنا المأزق الإعلامي والفكري، مستدعياً طروحات المفكر محمد جابر الأنصاري حول التغيير وإصلاح العقل العربي نقاش يفكك معادلة النفوذ والإعلام، ويحدد بدقة أين تقف حرياتنا الفكرية اليوم. محاور الحلقة: • خناق السلطة وفوضى التواصل: المعادلة الصعبة بين خوف الأنظمة من الصوت الحر والتخبط الرقمي في الشبكات الاجتماعية. • شجاعة الاعتراف بالخلل: كيف يمثل نقد الذات الخطوة الأولى والوحيدة للخروج من حلقة الفشل الحضاري؟ • فلسفة التعليم والوعي: البنية التحتية للعقول؛ هل نصنع أجيالاً مفكرة أم نكتفي بالمناهج التلقينية؟ • موقوفون عن التأثير: كيف تراجع مكان الصحفي الجاد لصالح قادة الرأي الجدد في البيئة الرقمية؟ 📌 آراء الضيوف لا تعبّر بالضرورة عن رأي القناة 📅 كل إسبوعين يوم الأحد على قناة حكاية في يوتيوب وجميع منصات البودكاست برعاية: 🧠📖 دارة م','https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/89bea567-3799-43a2-981e-fa04f5f3421b/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=89bea567-3799-43a2-981e-fa04f5f3421b&amp;feed=lhwIWvSy',6103,'2026-08-30T06:56:24Z'::timestamptz,0 FROM podcasts p WHERE p.title='ديوان' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/89bea567-3799-43a2-981e-fa04f5f3421b/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=89bea567-3799-43a2-981e-fa04f5f3421b&amp;feed=lhwIWvSy');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'التغريد خارج السرب مع جعفر سلمان','في هذه الحلقة من بودكاست ديوان، نفتح ملفاً شائكاً ومسكوتاً عنه حول واقع الثقافة والخطاب التنويري في مجتمعاتنا، ونطرح الأسئلة الأكثر جرأة: هل تراجع دور المثقف وأصبح يخشى مواجهة السائد؟ وكيف يؤثر استبداد الرأي والتراث على حرية التفكير وتطوير المجتمعات؟ نستضيف في هذه الحلقة جعفر سلمان ليحلل مفاهيم التعصب الطائفي، العقل الجمعي، وتكلفة قول الحقيقة في زمن البحث عن السلام. حوار صريح يتجاوز المجاملات ليضع النقاط على الحروف في قضايا الهوية، نقد الذات، وتحديات التجديد. محاور الحلقة: • حقيقة دور المثقف: بين الشجاعة التنويرية وفخ الصمت والنفاق الثقافي. • مواجهة التراث: لماذا نخشى مراجعة الموروث ونكتفي بوهم الثبات؟ • سلطة الخطاب: كيف يؤثر الاستبداد ورجال الدين على صياغة الوعي الجمعي؟ • الهوية والتعصب: تفكيك أسباب الشحن الطائفي والتراجع التنويري في المنطقة. 📌 آراء الضيوف لا تعبّر بالضرورة عن رأي القناة 📅 كل إسبوعين يوم الأحد على قناة حكاية في يوتيوب وجميع منصات البودكاست برعاية: 🧠📖 دارة محمد جابر الأنصاري للفكر والثقافة 🎬 فريق العمل: 🎙️ تقديم: الإعلامية القديرة إيمان مرهون ✍🏻 إعداد: الهنوف الشمري ✂️','https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/bdf6389d-907c-4a67-96a2-7b1bbfc1536d/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=bdf6389d-907c-4a67-96a2-7b1bbfc1536d&amp;feed=lhwIWvSy',5382,'2026-08-16T08:34:10Z'::timestamptz,0 FROM podcasts p WHERE p.title='ديوان' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://injector.simplecastaudio.com/708a6f98-54f1-4ca0-9fc2-6f921f41ef7c/episodes/bdf6389d-907c-4a67-96a2-7b1bbfc1536d/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=708a6f98-54f1-4ca0-9fc2-6f921f41ef7c&amp;awEpisodeId=bdf6389d-907c-4a67-96a2-7b1bbfc1536d&amp;feed=lhwIWvSy');

