SELECT '3ee18806-4cca-54c4-afd9-71ed1fa3e10d'::uuid,'بودكاست علمي جدًا','بودكاست علمي عربي يبسط المفاهيم العلمية والظواهر الغريبة بأسلوب خفيف وواضح، يقدمه أحمد سمير من إنتاج كيرنينج كلتشرز.','أحمد سمير','أحمد سمير مقدّم بودكاست علمي جدًا، يقدم العلوم بشكل مبسط وممتع للجمهور العربي.','0eacf812-edae-4159-9b9d-b91c71d6f3cb'::uuid,'scientific','https://assets.pippa.io/shows/644194d3996c1700114133bf/show-cover.jpg','beginner',(SELECT id FROM hosts WHERE name_ar='أحمد سمير' LIMIT 1),0,0,NOW()
