INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'بزنس المحتوى','بودكاست بزنس المحتوى: أجدد إنتاجات شبكة كيرنينج كلتشرز للاستماع للبودكاست يمكنكم زيارة هذا الرابط: https://link.chtbl.com/businessalmohtawa في هذا البودكاست، نتعرّف على صُنّاع المحتوى والتحديات التي يواجهونها، ونكتشف عن قُرب عالم صناعة المحتوى بكل أشكاله وأبعاده. يقدّم هذا البودكاست محمد الفضل وتنتجهُ نيما صالحة وأماني عادل. إدارة الإنتاج لأحمد عطار و الإشراف التحريري لهبة عفيفي ورند خضير. البحث وتدقيق الحقائق لدينا صبري. إشراف فني وأنيميشن لتالا تكلي. الإشراف على الصوت والفيديو لمحمد خريزات والتصميم الصوتي ليوسف دوازو وأحمد متري. التصوير لمعاذ مجيد والمونتاج لسولو فيلمز. التصميم الجرافيكي والهوية البصرية لأحمد سلهب. Hosted on Acast. See acast.com/privacy for more information.','https://sphinx.acast.com/p/open/s/644194d3996c1700114133bf/e/648216cc8a971b00113f8e0d/media.mp3',221,'2023-06-08T17:58:35Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست علمي جدًا' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://sphinx.acast.com/p/open/s/644194d3996c1700114133bf/e/648216cc8a971b00113f8e0d/media.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'طارق أبو الذهب','ماذا لو اقترحنا عليكم برنامجا آخر من إنتاجات شبكة كيرنينج كلتشرز؟ حلقة اليوم تأتيكم من بودكاست بحب، للاستماع للمزيد من الحلقات يمكنكم زيارة هذا الرابط: https://link.chtbl.com/bhob نستمع لقصة طارق أبو الذهب مع ركوب الدراجات، قصة مليئة بالطموح والتجارب المفعمة بالحياة. يأخذنا طارق معه على مسار الذكريات عبر لبنان ومصر وفرنسا، ونمشي على طريق درّاجته لنتعرّف على طارق البطل وطارق الإنسان. هذه الحلقة من إنتاج نيما صالحة، جاء بالفكرة ودعم في الإنتاج فينبار أندرسون. تحرير أحمد فتيحة. التصميم صوتي لبول ألوف، و التصميم الجرافيكي لأحمد سلهب. Hosted on Acast. See acast.com/privacy for more information.','https://sphinx.acast.com/p/open/s/644194d3996c1700114133bf/e/54c34fb6-5845-4b23-9de0-afe401193b37/media.mp3',1772,'2023-04-17T06:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست علمي جدًا' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://sphinx.acast.com/p/open/s/644194d3996c1700114133bf/e/54c34fb6-5845-4b23-9de0-afe401193b37/media.mp3');
