SELECT p.id,'بودكاست درب: الذكاء الصناعي الاستخدام الجيد والسيء','السلام عليكم ورحمة الله وبركاته اخوكم عبدالله الحصيني، موضوعنا هو استغلال الذكاء الصناعي الجيد والاستخدام السيء. في ضل تغير التعامل حول التقنية من "لازم نحطه بكل مكان" إلى "التكاليف قتلتنا" حسيت انه الفرصة المناسبة للتحدث عن كيف تستغل هذي التقنية بشكل صححي المراجع ١ المبرمج الذي بدأ باستخدام الذكاء الصناعي لفحص البرمجيات https://www.linkedin.com/in/pjullrich/ ٢ البحث الذي تكلم على اثر البرومبت بالتعرف على النصوص https://arxiv.org/pdf/2604.16504 ٣ بحث حول قراءة المخطوطات القديمة بالذكاء الصناعي https://arxiv.org/pdf/2507.04132 ٤ منشوري على لنكدن بنفس الموضوع https://www.linkedin.com/posts/abdullah-alhusaini-9932531b4_bad-ai-vs-good-ai-a-systems-compliance-share-7469281729762160640-mu0W/?utm_source=share&utm_medium=member_desktop&rcm=ACoAADHexr8BTR-bfNK26-a5S7NvUJQv9kudQpc ٥ اختراق ميتا المذكور بالحلقة https://www.404media.co/hackers-simply-asked-meta-ai-to-give-them-access-to-high-profile-instagram-accounts-it-worked/','https://www.buzzsprout.com/2007857/episodes/19318402-.mp3',605,'2026-06-09T07:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست درب' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://www.buzzsprout.com/2007857/episodes/19318402-.mp3');
