SELECT p.id,'API - تعريفه وكيف تتعامل معه','مساكم الله بالنور والسرور، في هذي الحلقة تكلّمنا عى فكرة ال API وكيف تتعامل معه هذه الحلقة كانت بناء على طلب أحد المشتركين في مجموعتي على دسكورد.. انضم خلال هذا الرابط: https://discord.gg/jbwnf2eep7','https://www.buzzsprout.com/2007857/episodes/14540250-api.mp3',340,'2024-02-20T18:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست درب' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://www.buzzsprout.com/2007857/episodes/14540250-api.mp3');
