SELECT p.id,'البحث الذكي بستخدام Word2Vec','موضوع اليوم كان عن طرق البحث الذكي أي: البحث الذي يأتي بنتائج صحيحة دون أن تشمل المصطلح الذي استخدمه الباحث. مقال يعطي تفاصيل عامّة عن فكرة word2vec: https://www.coveo.com/blog/word2vec-explained/ مقال يشرح كيفيّة بناء نظام مثل هذا بستخدام بايثون و numpy: https://towardsdatascience.com/a-word2vec-implementation-using-numpy-and-python-d256cf0e5f28 أستخدام لفكرة word embeddings لصنع LLM يقرأ مؤلّف من مؤلّفات أفلاطون وكيفيّة صنعه باستخدام Python: https://machinelearningmastery.com/how-to-develop-a-word-level-neural-language-model-in-keras/','https://www.buzzsprout.com/2007857/episodes/12783353-word2vec.mp3',386,'2023-05-04T13:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست درب' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://www.buzzsprout.com/2007857/episodes/12783353-word2vec.mp3');

