SELECT p.id,'محمد الديب | اصطياد الثغرات والهجوم على الأنظمة | Offensive Security','تعرف ان فيه وظيفة اسمها صياد ثغرات ؟ Bug Bounty Hunter لو انت بتقرر تدخل في عالم الامن السيبراني فبتكون افضل واسهل مدخل ليك ..وبيتعمل مساقبات عالمية ممكن تكسب فيها جوايز 100,000 دولار واكتر 🔥 بس طبعا الاحتراف فيها مش سهل وبياخد وقت وبتغامر كتيير لانك ممكن تقعد احيانا بالشهور من غير متوصل لحاجة والناس الشاطرة كتير فالمنافسة عالية..استضفنا المهندس Mohammed Eldeeb اللي بدأ كصياد ثغرات وما شاء الله عليه انهاردة متخصص في الRed Team وبيقدم خدمات للموسسات المالية لتأمينها من الثغرات. حلقة ثرية ومعلومات مفيدة جدا لكل حد مهتم يسمع الجوانب ده من عالم الامن السيبراني.','https://anchor.fm/s/fa0dcd34/podcast/play/113653342/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-0-7%2F97feaf28-fbc3-675b-147f-97d193b2da2f.mp3',5055,'2026-01-10T15:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/113653342/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-0-7%2F97feaf28-fbc3-675b-147f-97d193b2da2f.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'عمر سلام | ازاي تشتغل في شركة بوكينج | Booking.com Product Manager','شركة بوكينج .. هل المنصة بتاعتهم معقدة ؟ويمكن دايما المستخدم مش بيشوف غير النتيجة النهائية لما يجي يعمل بحث عن حجز فندق او شالية ..لكن وراء المواليس عشان النتايج ده توصلك صح وتبقى دقيقة ففيه قرارات كتيرة بتتعمل في الProduct عشان يطلع بالمنظر ده .. وده معناه ان فيه ناس مهندسين .. وProduct Managers شاطرين شغالين في منصة عملاقة زي ده ..تعالوا نتعرف على الشغل وراء الكواليس في شركة بوكينج والتفكير في محرك البحث بتاعهم بيحصل ازاي مع الخبير الاسترتيجي Omar Sallam .. وهو مش مجرد شاطر كمدير منتج .. ده كمان اسس مجتمع للناس المهتمة بالتوجه ده اللي هو بقى ركن اساسي في نجاح جميع المنصات لانه هو اللي بيشتغل يوم بيوم مع المهندسين عشان يحققوا المنصات القوية اللي احنا مبقيناش بنستغنى عنها في حياتنا .. المجتمع اسمه برودكت بلس Prdkt+ | برودكت بلس .. وبيعملوا Summit سنوي في القاهرة باذن الله هكون Speaker هناك يوم 31/1/2026 .. هعلن قريب عن التفاصيل والحجز للي حابب نتقابل هناك 🤝🔥 حلقة قوية ومفيدة للناس في البيزنس والمعندسين اكتر كمان عشان يعرفوا ازاي يشتغلوا في شركات عملاقة زي بوكينج وينجحوا فيها صح 🔥🔥🚀🚀','https://anchor.fm/s/fa0dcd34/podcast/play/113653017/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-0-7%2F63f774fd-d578-b9d9-f6eb-0f8c6436d205.mp3',7081,'2026-01-07T19:32:18Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/113653017/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-0-7%2F63f774fd-d578-b9d9-f6eb-0f8c6436d205.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف تبني مسارك المهني في الكلاود داخل الشركات الكبرى؟ | محمود عطالله','تعالوا نتكلم بجد عن الكلاود في الشركات الكبيرة 👀مش أي كلاود .. نتكلم عن الشركات اللي بتبني أنظمة بتخدم ملايين المستخدمين يوميا.كتير من الناس لسه شايفة إن الـ Cloud مجرد:سيرفر أو Hosting .. تعمل عليه Deploy وخلاصلكن الحقيقة إن الموضوع أعمق وأعقد بكتير.في الشركات الكبيرة، الكلاود يعني:- قرارات معمارية مصيرية- Cost optimization وتسعير محسوب- Scalablity حقيقي وقت الضغط- High Availability وBusiness Continuity- Security وCompliance على مستوى مؤسسيوده كله بيقع تحت دور وظيفي مهم جدا اسمه Cloud Solutions Architect.في حلقة النهارده، معانا المهندس Mahmoud A. ATALLAH خبرة أكتر من 15 سنة في الـ IT والـ Infrastructure داخل شركات كبرى.حاليًا يشغل منصب استراتيجي كـHead of Azure Solutions في Bespin Global MEA, an e& enterprise company وهي شركة تابعة لمجموعة e& UAE (اتصالات الإمارات).شغله اليومي هو تصميم وبناء Cloud Architecturesلمشاريع ضخمة بتخدم ملايين المستخدمين على مستوى المنطقة.شوفوا الحلقة هتستفادوا من خبرات قوية جداً شاركها معانا ومعلومات عن ازاي تنجح صح في اتجاه الكلاود في الشركات الكبرى.','https://anchor.fm/s/fa0dcd34/podcast/play/112938198/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-11-21%2F82a35b27-d631-7f72-5342-c3ea771ba901.mp3',6647,'2025-12-21T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/112938198/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-11-21%2F82a35b27-d631-7f72-5342-c3ea771ba901.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل هندسة الاتصالات اختيار غلط؟ وليه ناس كتير بتهرب من المجال؟ | عمرو أشرف','كل سنة آلاف الطلبة بيتخرجوا من هندسة اتصالات.وكل سنة عدد كبير منهم… بيسيب المجال.ناس بتتحول لبرمجة .. ناس تروح Product أو Data .. وناس تخرج من مجال التكنولوجيا بالكامل! والغريب إن ده بيحصل في وقت .. كل نجاح تقني حوالينا مبني أساسا على الاتصالات.الإنترنت اللي بنستخدمه كل يوم .. الموبايل نت .. الـ Cloud .. وحتى الـ AI والأنظمة الموزعة .. كل ده مش هيشتغل من غير Backbone اتصالات قوي. فالسؤال الحقيقي هنا: - ليه مهندسين كتير بيسيبوا مجال الاتصالات؟ - هل هندسة الاتصالات اختيار غلط فعلًا؟ - ولا المشكلة في إننا مش فاهمين المجال صح؟ - وشكل النجاح فيه عامل إزاي النهارده؟ في الحلقة رقم (48) من كلام في البرمجة .. قعدت أتكلم مع Amr Ashraf واحد من الناس اللي عايشين جوه المجال ده بقالهم سنين طويلة. عمرو اشتغل في قلب صناعة الاتصالات: - من تشغيل LTE و 5G RAN Optimization - لقيادة R&D و Solution Architecture في DIGIS Squared - وشارك في تنفيذ أول شبكة Open RAN تجارية في السعودية - وساهم في بناء منتجات اتصالات بتستخدمها شركات عالمية','https://anchor.fm/s/fa0dcd34/podcast/play/111916900/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-30%2F1c1695c4-7bae-0be6-d974-d8d720e11fc8.mp3',7394,'2025-12-13T14:45:39Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/111916900/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-30%2F1c1695c4-7bae-0be6-d974-d8d720e11fc8.mp3');
