SELECT p.id,'DevOps & Infrastructure | كيف تصبح ديف اوبس ناجح ؟ - محمد موسى','-','https://anchor.fm/s/fa0dcd34/podcast/play/111746309/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-26%2F703fed4a-713e-0847-a689-9154b104220e.mp3',6590,'2025-11-29T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/111746309/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-26%2F703fed4a-713e-0847-a689-9154b104220e.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'| Microservices vs Monolith | الميكروسيرفس ولا المونوليث؟ - حسن إبراهيم','هل Microservices أفضل من الMonolith ؟ 🤔 في الحلقة دي استضفنا الخبير في هيكلة وتطوير الأنظمة البرمجية .. المهندس Hassan Ibrahim 🇵🇸 وهو حالياً شغال Principal Software Engineer في شركة Foodics وهي احدي أكبر شركات ادارة انظمة المطاعم والكافيهات في الشرق الأوسط. تناقشنا ودخلنا بعمق في التحديات المختلفة التي بناء عليها بتاخد القرار انك محتاج Microservices Architecture في النظام عندك. وده قرار صعب بيواجهه أي مهندس أو تيم شغال في مشروع جديد أو مشروع قديم Legacy عايزين ننقله نقلة نوعية عشان يخدم اتجاهات جديدة في البيزنس. هل تبدأ بـ Monolith ولا تدخل من الأول في Microservices ؟ وإمتى فعلاً القرار ده بيكون صح ؟ هتسمع رأي حسن في المايكروسيرفس وليه ممكن تبقى سلاح ذو حدين وهنتكلم كمان عن لحظة التحول بعد الـ MVP وازاي التريد أوف Tradeoff الحقيقي بيكون بين سهولة التطوير واستقرار السيستم. وفي نص الحلقة بنغوص في عالم الـ Domain Driven Design 🔥 هل لازم تتعلمه بالكامل ولا تاخد منه اللي يخدم مشروعك ؟ اسمع الحلقة من هنا وحقيقي مهمة جدا مينفعش تفوتها','https://anchor.fm/s/fa0dcd34/podcast/play/110566777/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-2%2Fa1169f89-8c09-87a9-f12c-9d5e2995f036.mp3',7320,'2025-11-02T17:05:49Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/110566777/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-2%2Fa1169f89-8c09-87a9-f12c-9d5e2995f036.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'Database Administrator | ازاي الشركات بتأمن بياناتها ؟ - أحمد نجيب','️ كلام في البرمجة | ليه ممكن أنصح العميل بـ Excel… ومين أستحق أقوله “روح لأوراكل”؟ 💻☕ ليه ساعات أقول للعميل “خليك على Excel”، وساعات تانية أقول له “حضّر ميزانية ملايين لأوراكل”؟ السر مش في الاسم… السر في الاحتياج، والوعي، والتخطيط 🎯 💡 فيه عميل صغير كل اللي محتاجه جدول بسيط، وفيه عميل تاني لو ماعملش نظام محترف، ممكن يضيع شغله كله في ثانية! اتكلمنا كمان عن: ☕ العلاقة بين إدارة البيانات والنسكافيه — سريعة التحضير، بس مش دايمًا نافعة 😄 🔐 أخطاء في أمن قواعد البيانات كلفت شركات ملايين 💾 وإزاي Oracle بتقدر تحميك قبل ما الكارثة تحصل لكن أهم جزء في الحوار كان عن الجيل الجاي 👇 إزاي نخلق جيل روّاد في التكنولوجيا مش مجرد ناس عندها شوية معلومات متفرقة، لكن ناس عندها رؤية، منهج، وتجربة حقيقية تبني بيها المستقبل','https://anchor.fm/s/fa0dcd34/podcast/play/110566631/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-2%2F377dcefc-9f99-0356-baec-179cd8a07d93.mp3',5607,'2025-11-02T11:06:24Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/110566631/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-2%2F377dcefc-9f99-0356-baec-179cd8a07d93.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'أحمد عادل - AI in Software Dev - إجبار المبرمجين على استخدام الذكاء الاصطناعي','ليه الشركات بقت بتجبر المبرمجين يستخدموا ادوات الـAI ؟ الموضوع بسيط .. مجال البرمجة طول عمره بيتطور .. والادوات ده سرعت اداء شغلنا وخليتنا ممكن ننتج احسن لو استخدمناها صح .. ده كان احد المحاور الاساسية اللي ناقشناها في حلقة بودكاست مع Ahmed Mohamed .. اللي بدأ رحلته كـAndroid Engineer لحد موصل وبقى Mobile Architect .. ومؤخرا بيركز اتجاه الفكر العام بتاع الSoftware Engineering .. أحمد كان بيقولنا ان الشركة فرضت عليهم استخدام Cursor وكان بيجوا يحسابوا لو ماستخدمهوش .. واتكلمنا اكتر في محاور الموضوع حلقة شيقة ومفيدة جدا استمتعت فيها واستفدت جدا منها .. شوفوا الحلقة وشاركونا بآرائكم 🌹','https://anchor.fm/s/fa0dcd34/podcast/play/108881402/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-27%2F07cd2b9a-be9d-4b0d-1e4a-02085347b1b3.mp3',7666,'2025-09-27T08:39:52Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/108881402/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-27%2F07cd2b9a-be9d-4b0d-1e4a-02085347b1b3.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'أهم بودكاست هتسمعه عن علوم البيانات - عمرو صالح | AI in Data Engineering','حلقة جديدة ومميزة جدًا من كلام في البرمجة عن علوم البيانات مع صديقي Amr Saleh, MSc. عمرو من الناس اللي بجد بتتعلم منهم كل مرة .. واحد من أقوى خبراء هندسة البيانات في المنطقة وصاحب شركة Kiwilytics اللي بتقدم حلول متقدمة لشركات كبرى عالميا 📈 الحلقة اللي فاتت مع عمرو حققت أكتر من 150 ألف مشاهدة وكان فيه طلب جماهيري انه ينورنا في حلقة تانية — والنهارده رجعنا بحوار أعمق وأوسع 🔥 🎓 عمرو كمان لسة منزل كورس يعملك كل حاجة محتاج تعرفها عشان تبقى Data Engineer شاطر وعامل خصم لفترة محدودة ٥٠٪ عن طريق اللينك ده: https://lnkd.in/dVTxzqf8 في الحلقة دي غطينا موضوعات حساسة ومهمة جدا عن تقاطع الذكاء الاصطناعي مع البيانات .. وازاي تطبيقات الـAI بتعتمد على جودة وتنوع الداتا. 💡 بعض المحاور اللي ناقشناها: 🔍 هل أقدر أثق في OpenAI أو أي Model بشكل كامل؟ 🧠 ليه التجربة العملية أهم من أي موديل جاهز؟ 🤖 إزاي بيستخدم عمرو الشات بوتس في شغله كـ Data Engineer؟ 🛠️ هل لازم أي Data Engineer يلتزم بتقنيات معينة ولا يفضل مرن؟ 👨‍💻 إزاي تبدأ وتبني مسارك كـ Data Engineer النهاردة؟ 📅 الروتين اليومي لمهندس البيانات.. وهل شهادتك','https://anchor.fm/s/fa0dcd34/podcast/play/107557533/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-30%2F356d4b21-98ed-31e9-c0f7-83bc2009e8b5.mp3',7062,'2025-09-21T09:21:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/107557533/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-30%2F356d4b21-98ed-31e9-c0f7-83bc2009e8b5.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل انتهى عصر الكمبيوتر التقليدي؟ - حسام احمد | Quantum Computing','🔮 هل الكوانتم كومبيوتنج هو مستقبل الكمبيوتر؟ وهل ممكن يغير شكل العالم اللي احنا عايشينه؟ 🖥️✨ في الحلقة الجديدة من بودكاست كلام في البرمجة استضفنا حسام أحمد ، واللي شغال على تطوير حلول تكامل مع الـ Quantum Systems. اتكلمنا معاه عن أساسيات الـ Quantum Computing بشكل مبسط، وإزاي التكنولوجيا دي ليها استخدامات حقيقية النهاردة. وبعدها دخلنا على التحديات الكبيرة اللي بتواجه المجال زي موضوع الـ Error Correction، واللي بيخلي بناء كمبيوتر كوانتم مستقر تحدي ضخم. كمان ناقشنا مستقبل الـ Quantum Computers خلال العشر سنين الجاية، وإمتى ممكن نشوف التبني الحقيقي للتكنولوجيا دي على نطاق واسع. وفي آخر الحوار، حسام شارك نصايحه: إزاي تبدأ في المجال، وهل لازم تسافر برة عشان تتعلمه، ولا ممكن تبدأ من مكانك. الحلقة مليانة insights قوية جدًا وهتخليك تشوف الكمبيوتر من زاوية مختلفة 🚀 📌 متفوتهاش وتفرج للنهاية.','https://anchor.fm/s/fa0dcd34/podcast/play/108018612/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-8%2F6a677315-a89f-05fc-4b2a-e839679a3da8.mp3',4742,'2025-09-08T16:55:48Z'::timestamptz,0 FROM podcasts p WHERE p.title='كلام في البرمجة' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/fa0dcd34/podcast/play/108018612/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-8%2F6a677315-a89f-05fc-4b2a-e839679a3da8.mp3');

