SELECT 'b22f9f93-eeb0-59b3-97d0-68ee4376f16c'::uuid,'Waee Podcast وعي بودكاست','بودكاست عربي عن الوعي الذاتي والنمو الشخصي والعلاقات والحياة، تقدمه تهاني روحي بأسلوب هادئ وعميق.','تهاني روحي','تهاني روحي مقدمة بودكاست وعي، تركز على الوعي الذاتي والنمو الشخصي والعلاقات من منظور عربي.','eb96e956-ce53-4b46-83e1-7d151594c8da'::uuid,'psychology','https://d3t3ozftmdmh3i.cloudfront.net/staging/podcast_uploaded_nologo/36555962/36555962-1723326849160-996e7314570bc.jpg','beginner',(SELECT id FROM hosts WHERE name_ar='تهاني روحي' LIMIT 1),0,0,NOW()
