SELECT p.id,'صور «قبل وبعد»… شو اللي خَبّوه عنك | د. سوزان البخيث','هل نريد فعلا تغيير ملامحنا، أم أننا اعتدنا رؤيتها بعيون الآخرين؟بين الفلاتر وصور «قبل وبعد» وترندات التجميل، قد تصبح ملامحنا الطبيعية غريبة عنا، ونبدأ بملاحقة صورة لا تشبهنا. كيف نميز بين رغبة نابعة منا وضغط يقنعنا بأننا بحاجة دائمة إلى التغيير؟في هذه الحلقة ، نستضيف الدكتورة الاردنية سوزان البخيت، استشارية جراحة التجميل والترميم والحروق، لنفتح حوارا صريحا عن علاقتنا بالجمال وأجسادنا، وعن مسؤولية الطبيب حين يكون الجواب الأنسب: «لا».نتحدث عن طلبات التجميل غير الواقعية، وحدود ما يمكن تحقيقه في غرفة العمليات، وما قد تخفيه صور النتائج من ألم وتعاف ومضاعفات. ونتوقف عمد العامل النغسب عم هدم الوضازىفقدان الهوية ما بعد العمليات، وأهمية اختيار الطبيب المؤهل وفهم تبعات القرار قبل اتخاذه.متى يكون التجميل خيارا واعيا، ومتى يتحول إلى ملاحقة لا تنتهي لصورة مثالية؟ وهل يكفي أن نغيّر ما نراه في المرآة ليتغيّر شعورنا تجاه أنفسنا؟شاركونا تجاربكم وآراءكم بالتعليقات : هل سبق وتأثرتوا بفلاتر السوشال ميديا أو فكرتم بعملية تجميل بسببها؟ #وعي #بودكاست_وعي #سوزان_البخيث #من_الفلتر_إلى_غرفة_العمليات #جراحة_التج','https://anchor.fm/s/da7c8f28/podcast/play/129339576/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-13%2F436619719-44100-2-87c67495d7d958.mp3',1995,'2026-11-13T02:04:58Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/129339576/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-13%2F436619719-44100-2-87c67495d7d958.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'ليش بنحس بالوحدة بين أصحابنا؟ | سحر دين برفار','هل يمكن أن نكون محاطين بالأصدقاء، ومع ذلك نشعر بالوحدة؟ ولماذا نبقى أحيانًا في صداقات تؤذينا خوفا من أن نبقى وحدنا؟في هذه الحلقة نحاور أخصائية الدعم النفسي سحر دين بارفار عن الصداقة الحقيقية، وحاجتنا إلى علاقات نشعر فيها بالأمان والفهم والانتماء.نتحدث عن أثر تجارب الطفولة إرضاء الآخرين والخوف من المواجهة، ونسأل: هل أصبح «البلوك» أسهل من الحوار؟ وهل صرنا نتعامل مع بعض الصداقات كأنها قابلة للاستغناء؟ونتوقف عند أسئلة تمس حياتنا جميعًا:▫️ لماذا نشعر بالوحدة رغم وجود الناس حولنا؟▫️ كيف نميّز الصداقة الحقيقية من العلاقة التي تؤذينا؟▫️ هل يجب أن نتشابه مع أصدقائنا، أم أن الاختلاف يقوّي الصداقة؟▫️ كيف نواجه الخلاف بطريقة صحية؟▫️ ما علاقة قيمنا وعلاقاتنا الاجتماعية بالشعور بالمعنى والرضا؟حوار عن العلاقات التي تساعدنا على أن نكون أنفسنا، وعن صداقة نفرح فيها لإنجاز الآخر ونتمنى له الخير. وشاركونا في التعليقات: ما الذي يجعل الصداقة حقيقية بالنسبة لكم؟اشتركوا في قناة وعي بودكاست وفَعّلوا التنبيهات لتصلكم حلقاتنا الجديدة.#وعي_بودكاست #الصداقة_الحقيقية #الوحدة #العلاقات_السامة','https://anchor.fm/s/da7c8f28/podcast/play/128774384/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-4%2F435874258-44100-2-05ffb4f75877a.mp3',1591,'2026-11-04T17:53:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/128774384/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-4%2F435874258-44100-2-05ffb4f75877a.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'علاقتك بملابسك… شو بتحكي عنك؟','خزانتك مليانة… بس ما عندك شي تلبسيه؟هون بتحتاجي لوضوح أكثر عن نفسك. هل بنلبس ما بيشبهنا، أم ما بيرضي الآخرين؟ وهل خزانتنا بتعبّر عن حياتنا اليوم، ولا عن نسخ قديمة منّا بنحاول نرجع إلها؟ في هذه الحلقة من وعي بودكاست، تستضيف #تهاني_روحي مستشارة ومدرّبة الستايل الشخصي والموضة نادين شاهين، في حوار يتجاوز تنسيق الملابس إلى علاقتنا بهويتنا وأجسادنا وثقتنا بأنفسنا. نفتح حكايات القطع اللي بنحتفظ فيها لذكرى سعيدة، أو على أمل نرجع لمقاس قديم. ونسأل عن علاقتنا بالألوان، وكيف تتغيّر اختياراتنا مع مشاعرنا والعمر والعمل وتجارب الحياة. ونحكي عن ضغط السوشال ميديا: ليش صرنا نتردّد نكرّر اللبسة؟ وهل بنختار إطلالتنا لأنفسنا، أم للكاميرا؟ وكيف بتدفعنا التخفيضات والمؤثّرون والموضة السريعة لشراء أكثر من حاجتنا؟ شو دور الـPersonal Stylist: هل تحتاج الاستعانة فيه إلى ميزانية ضخمة؟ وكيف ممكن يساعدنا نكتشف قطعنا من جديد، وننسّق القطعة الواحدة بأكثر من طريقة، ونبني خزانة عملية بتناسب حياتنا؟ ومن ترتيب الخزانة واختيار الترند المناسب، إلى الاستفادة من الذكاء الاصطناعي في تنسيق الإطلالات، نبحث عن خيارات فيها #وعي ا','https://anchor.fm/s/da7c8f28/podcast/play/128011084/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-24%2F434898685-44100-2-2fa9b2f7e19ad.mp3',2010,'2026-10-24T18:52:30Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/128011084/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-24%2F434898685-44100-2-2fa9b2f7e19ad.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'صحفي أم صانع محتوى | د. ربى زيدان | بودكاست وعي','في زمن يستطيع فيه أي شخص أن يصوّر وينشر ويصل للملايين، تتنافس الصحافة وصناع المحتوى والخوارزميات على انتباهنا. في هذه الحلقة من #بودكاست_وعي، تحاور تهاني روحي الدكتورة ربى زيدان، أستاذة الإعلام الرقمي ونائب عميد كلية الاعلام في جامعة البلقاء التطبيقية #الأردن ، حول مستقبل الصحافة، وتأثير المنصات في خياراتنا، والمسؤولية التي ترافق صناعة المحتوى ونشره. نسأل لماذا استطاع صانع المحتوى الوصول إلى جمهور لم يصل إليه الصحفي المحترف، وهل ابتعدت الصحافة عن لغة الناس واهتماماتهم؟ ونناقش الفرق بين الانتشار والقيمة في هذه الحلقة نناقش: ▪️ هل ما زالت خياراتنا حرة، أم أن الخوارزمية تدرّبنا على رغبات جديدة؟ ▪️ لماذا وصل صانع المحتوى إلى جمهور عجز عنه الصحفي المحترف؟ ▪️ الصحافة في قفص الاتهام: هل ابتعدت عن لغة الناس وحياتهم؟ ▪️ هل يمكن أن تكون صورة حقيقية ومؤثرة… لكنها غير أخلاقية؟ ▪️ هل ما زال لدينا واقع مشترك، أم صار لكل مجموعة حقائقها؟ ▪️ الذكاء الاصطناعي: ماذا يبقى للصحفي الإنسان؟ ▪️ محاكمة كليات الإعلام: هل ننصح شابًا طموحًا اليوم بدراسة الإعلام؟ حوار يدعونا إلى التأمل في علاقتنا بما نقرأ ونشاهد و','https://anchor.fm/s/da7c8f28/podcast/play/127326574/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-12%2F433977699-44100-2-20c236cfa22c4.mp3',2111,'2026-10-12T10:20:08Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/127326574/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-12%2F433977699-44100-2-20c236cfa22c4.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'لماذا نكره أجسادنا؟ وصمة الوزن - مع اخصائية التغذية العلاجية ديمة الكيلاني','هل فعلًا أجسامنا بحاجة إلى التغيير، أم أن المشكلة في الصورة التي رسمها لنا المجتمع عن الشكل المثالي؟ في هذه الحلقة من بودكاست وعي، نحكي مع عن وصمة الوزن الزائد والتنمر الذي قد يأتي أحيانًا على شكل “نصيحة”. نناقش كيف تؤثر نظرتنا لأجسادنا على صحتنا النفسية، ولماذا لا تختصر الصحة برقم على الميزان، وكيف نواجه ضغط السوشيال ميديا والحلول السحرية بطريقة أكثر وعيًا ورحمة.وننتقش في ي هذه الحلقة:🔹 كيف تبدأ علاقتنا الصعبة بأجسادنا من البيت والمدرسة🔹 مَن صنع صورة «الجسم المثالي» على وسائل التواصل الاجتماعي؟🔹 عبارات تبدو مديحًا لكنها تؤذي🔹 الحمية القاسية، والأكل العاطفي، وتأثير «خربت الدايت… خلص!»🔹 هل يقول الميزان الحقيقة كلها عن صحتنا؟🔹 دخلاء مهنة التغذية: قبل أن تشترك، اسأل: هل هذا الشخص مختص؟#شاركونا بالتعليقات: ما أول تعليق سمعتموه عن أجسادكم وما زال عالقًا في ذاكرتكم؟🔔 اشتركوا في القناة وفعّلوا الجرس لتصلكم حلقات وعي الجديدة. استمعوا إلى بودكاست وعي على #سبوتيفاي #ساوند_كلاود توقيت الحلقة 00:00 المقدمة01:21 متى تبدأ مشكلة الجسم؟02:38 نصيحة أم تنمر؟02:59 الحديث مع الأبناء عن الوزن04:09 كوني قدو','https://anchor.fm/s/da7c8f28/podcast/play/126431779/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-29%2F432898544-44100-2-41a877911bb7f.mp3',2155,'2026-09-29T10:52:02Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/126431779/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-29%2F432898544-44100-2-41a877911bb7f.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف وصل الأردن لكأس العالم 2026؟','هل وصول الأردن إلى كأس العالم 2026 كان صدفة؟ أم نتيجة مشروع طويل بدأ قبل سنوات؟في هذه الحلقة الخاصة من Waee Podcast تستضيف الإعلامية تهاني روحي، أمجد المجالي، رئيس اتحاد الإعلام الرياضي الأردني، في حوار عميق حول رحلة المنتخب الأردني إلى كأس العالم 2026، وأسرار نجاح النشامى، ودور الإعلام الرياضي والجمهور في صناعة هذا الإنجاز التاريخي.نتحدث عن:• كيف أصبح الأردن أول منتخب عربي يحسم تأهله إلى كأس العالم 2026؟• قصة "العظماء السبعة" الذين سافروا خلف المنتخب إلى الصين عام 2004• المدرسة المغربية وأثرها في نجاح المنتخب الأردني• يزن النعيمات وموسى التعمري وصناعة جيل تاريخي• الجمهور الأردني وثقافة البطاقة المجانية• كيف نحافظ على نجاح المنتخب الأردني بعد التأهل للمونديال؟التأهل إلى كأس العالم ليس نهاية الطريق، بل بداية اختبار جديد: كيف نبني منتخباً قادراً على الاستمرار والمنافسة في أكبر بطولة كروية في العالم؟#المونديال #منتخب_الأردن #النشامى #كأس_العالم #الإعلام_الرياضي#أمجد_المجالي #Waee_Podcast #بودكاست_أردني #كرة_القدم_الأردنية#المنتخب_الأردني #العظماء_السبعة #موسى_التعمري #يزن_النعيمات#WaeePod','https://anchor.fm/s/da7c8f28/podcast/play/121499804/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-5-17%2F426306452-44100-2-92cd6cb65f607.mp3',2245,'2026-06-17T10:07:04Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/121499804/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-5-17%2F426306452-44100-2-92cd6cb65f607.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل الشغف بطعمي خبز؟ | حقيقة التسويق الإلكتروني بعيدًا عن الوهم','"اشتري الكورس وبتصير مليونير بأسبوعين!".. قديش بنسمعها وقديش بنشوف شباب بضيعوا ورا وهم الربح السريع؟ في هذه الحلقة من بودكاست وعي، نستضيف خبير التسويق الرقمي والتجارة الإلكترونية ​⁠ مؤسس منصة مكسوب ورئيس الاكاديمية الدولية للتجارة الإلكترونية واللوجستيك في حوار صريح وجريء جداً يكشف فيه كواليس النصب الإلكتروني وحقائق الكسب (وليس الربح) من الإنترنت.','https://anchor.fm/s/da7c8f28/podcast/play/120411698/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-4-23%2F424719027-44100-2-f312a1d895526.m4a',2223,'2026-05-23T00:28:18Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/120411698/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-4-23%2F424719027-44100-2-f312a1d895526.m4a');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل يتحكم الذكاء الاصطناعي في طعامنا؟ حقائق صادمة مع د. تاتيانا الكور.','في هذا اللقاء العميق، نستضيف الدكتورة تاتيانا الكور، استشارية التغذية الطبية وباحثة علم النفس الإعلامي، لنكشف الستار عن العلاقة المعقدة بين ما نأكله، وما نشاهده على شاشاتنا، وكيف يقوم الذكاء الاصطناعي بإعادة صياغة سلوكنا الغذائي.','https://anchor.fm/s/da7c8f28/podcast/play/119736372/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-4-9%2F1f4accd9-b144-9e7d-fc04-399f6f68a034.mp3',1885,'2026-05-09T15:08:19Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/119736372/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-4-9%2F1f4accd9-b144-9e7d-fc04-399f6f68a034.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كذبة "الأكل الصحي" وفخاخ السوبر ماركت.. كيف تتسوق بوعي؟ 🛒 | بودكاست وعي مع امتثال جرار','"مش كل شي مكتوب عليه دايت يعني صحي، ومش كل شي غالي يعني جودته أعلى!" 🧐 في هذه الحلقة من بودكاست وعي، نستضيف أخصائية التغذية العلاجية امتثال جرار لنكشف الستار عن أسرار السوبر ماركت. هل فكرت يوماً أن قسم "الأكل الصحي" قد يحتوي على أفخاخ تسويقية؟ أو أن "اللايت" ليس دائماً الخيار الأفضل؟ في هذه الحلقة سنتعلم: ✅ قاعدة الـ 5% والـ 20%: تريك بسيط يغنيك عن حفظ الأرقام المعقدة عند قراءة الملصق الغذائي. ✅ فخ اللحوم والبروتين: لماذا جودة البروتين أهم من كميته؟ وكيف تختار القطعة الأنسب لصحتك. ✅ التسوق بذكاء: نصائح عملية للموظفين والأمهات للتسوق بوعي رغم ضيق الوقت. ✅ هوس البدائل: هل حليب اللوز والشوفان ضرورة صحية أم مجرد تريند تسويقي؟ ✅ الدهون الصحية: كيف تفرق بين الدهون المشبعة والمتحولة وتختار ما يفيد جسمك. الحياة حلوة والأكل زاكي، والسر دائماً في "الوعي". استمتعوا بالحلقة وتعلموا كيف تملؤون سلتكم بذكاء! 🍏🛒','https://anchor.fm/s/da7c8f28/podcast/play/119035281/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-3-25%2F422856354-44100-2-7356d3cde1ca5.m4a',1875,'2026-04-25T15:24:31Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/119035281/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-3-25%2F422856354-44100-2-7356d3cde1ca5.m4a');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'من الخوف إلى التفاوض: قصة 114 عاملة غيّروا واقع المزارع في الأغوار | بودكاست وعي','في حقول الأغوار الشمالية، بتشتغل آلاف النساء كركيزة أساسية للزراعة.. لكن، شو بيصير لما يقرر الصمت إنه ينكسر؟ 🤔 في هذي الحلقة من بودكاست وعي، وبرعاية ودعم من شريكنا مؤسسة "أهل"، ما بنحكي عن "ضحايا"، بنحكي عن بطلات. بنحكي عن باسمة وريما، وعن 114 عاملة قرروا يحولوا الخوف لخطة، والمعرفة لتنظيم، والتنظيم لانتصار حقيقي في 11 مزرعة. رح نغوص في رحلة التغيير من البداية: التحول: متى صار الصمت أثقل من المواجهة؟ وقصة مشغل التمر. - التكتيك: ليه اختاروا "أدوات السلامة" كبداية لمعركتهم؟ وكيف جمعوا بعض؟ لحظة الحقيقة: كواليس التفاوض مع أصحاب المزارع.. وكيف واجهوا جملة "إنتو ناس مشكلجية"؟ - معنى الإنجاز: شو الشعور لما تشوفي حقك صار واقع ملموس ونظام متبع؟ هذه الحلقة هي دليل لكل إنسان حاسس بقلة الحيلة، ليعرف إن القوة ما بتبدأ بالصوت العالي.. بل بالشخص الثاني اللي بيوقف جنبك. 🤝 #قوة_الناس','https://anchor.fm/s/da7c8f28/podcast/play/118293092/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-3-11%2Ffed02c35-b25a-d399-1042-80fd5c5c037b.mp3',2107,'2026-04-11T14:50:22Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/118293092/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-3-11%2Ffed02c35-b25a-d399-1042-80fd5c5c037b.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'ليه بنحب وبنبعد؟ الصمت العقابي في العلاقات مع سوزان الخطيب | بودكاست وعي','ليه بنحب… وبنبعد؟ سؤال بسيط، لكنه بيحمل وجع وأسئلة عاشها كثير من الأزواج. في هذي الحلقة من بودكاست وعي، نفتح ملف الفتور العاطفي بعد الزواج.. بدون لوم، وبدون ما ندّور على مين الصح ومين الغلط. هذي حلقة عن الفهم، عن العلاقات لما تتعب، وعن كيف نكمّل رحلتنا بدون ما نكسر بعض. مع ضيفتنا الأستاذة سوزان الخطيب، أخصائية تطوير الذات ومستشارة العلاقات الأسرية والإنسانية، بنحكي بصراحة وهدوء عن أشياء كثير منّا بيعيشها وراء الأبواب المغلقة: 🔸 متى بيكون الفتور بالعلاقة طبيعي ومرحلة بتمر؟ والفرق بينه وبين الانسحاب العميق. 🔸 كيف بتسرق الضغوط اليومية الحب من بيناتنا بدون ما ننتبه؟ 🔸 أخطاء شائعة بندفع ثمنها غالي: الصمت، تأجيل الكلام، وافتراض إن الطرف الثاني "فاهم لحاله". 🔸 الصمت العقابي: متى بيكون حكمة وتهدئة للنفوس؟ ومتى بيتحول لسلاح وعقاب وإيذاء؟ 🔸 ليه بنحكي مع بعض كثير.. بس ما بنفهم بعض؟ 🔸 وكيف نختار المختص النفسي والأسري الصح، ونبعد عن نصائح السوشال ميديا السطحية اللي ممكن تخرب بيوتنا. الفتور مش هو النهاية.. والخلاف أبداً ما بيعني الفشل! الوعي، لغة الحوار، وطلب المساعدة هم القوة الحقيقية لأي علاقة. 💬 ','https://anchor.fm/s/da7c8f28/podcast/play/117728521/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-2-31%2Fdf018fdb-71ca-d5c7-0a3c-c633061c93f7.mp3',1711,'2026-03-31T06:51:07Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/117728521/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-2-31%2Fdf018fdb-71ca-d5c7-0a3c-c633061c93f7.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'سن الأمل بعيداً عن الخرافات.. لماذا تعاني النساء بصمت؟','مزاج متقلب؟ أرق؟ إرهاق؟ العمر مش هو السبب! في هذه الحلقة من بودكاست وعي، نفتح ملف "سن الأمل" وما قبله بعيدًا عن الخرافات، مع الصيدلانية الأخصائية الأردنية زينب إياس. نساء كثيرات يعشن هذه المرحلة دون تشخيص واضح، ويعانين من التعب والضغط النفسي تحت مبرر "طبيعي مع العمر"، بينما الحقيقة أعمق وأكثر ترابطًا. هذه الحلقة لكل امرأة تريد أن تفهم جسدها بدل أن تخاف منه؛ فسن الأمل مرحلة تحتاج فهمًا، احتواءً، ووعيًا.','https://anchor.fm/s/da7c8f28/podcast/play/117075056/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-2-17%2Fe466a643-daae-02a6-2c27-9a7cdc7060bd.mp3',1911,'2026-03-17T18:28:17Z'::timestamptz,0 FROM podcasts p WHERE p.title='Waee Podcast وعي بودكاست' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/da7c8f28/podcast/play/117075056/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-2-17%2Fe466a643-daae-02a6-2c27-9a7cdc7060bd.mp3');

