SELECT 'a9ea8d9e-9bfb-501e-b001-7b918b375c6e'::uuid,'الدويتو','بودكاست رياضي عربي شهير يقدمه حذيفة وجيزاوي، يناقش كرة القدم والبطولات والأحداث الرياضية بتحليل وعفوية.','حذيفة وجيزاوي','حذيفة وجيزاوي يقدمان بودكاست الدويتو، أحد البرامج الرياضية العربية الشهيرة التي تناقش كرة القدم والبطولات بأسلوب تحليلي ممتع.','daaed3b4-1584-4db8-b5a9-e38de540a6b1'::uuid,'sports','https://www.omnycontent.com/d/programs/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/image.jpg?t=1700643137&amp;size=Large','beginner',(SELECT id FROM hosts WHERE name_ar='حذيفة وجيزاوي' LIMIT 1),0,0,NOW()
