INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل حظوظ برشلونة في الفوز بدوري الأبطال "صفر" كما اعترف رودري حقاً؟ | بودكاست الدويتو','هل كشفت خماسية ألمانيا حقيقة مستوى تشافي التدريبي؟ يناقش حذيفة وجيزاوي في هذه الحلقة من بودكاست الدويتو انهيار هولندا أمام ألمانيا بعد فوزها بسباعية على اليونان، وأسباب تذبذب أداء تشافي، إلى جانب انتصار إنجلترا على إسبانيا. وتتناول الحلقة تصريحات رودري عن ضعف فرص برشلونة في دوري أبطال أوروبا، وأزمة رافينيا مع البرازيل، وتأثير عودة فينيسيوس على ريال مدريد وخيارات مورينيو الفنية، ومستقبل المنافسة الأوروبية بين القطبين الإسبانيين. كما يناقشان تجربة تشافي السابقة مع برشلونة، وإنجازاته في الفوز بالدوري والاعتماد على المواهب الشابة، وخلافاته مع إدارة لابورتا التي انتهت برحيله. ويبحثان أسباب تعثره التدريبي رغم امتلاكه أفكارًا فنية مميزة، وما إذا كانت الانتقادات الموجهة إليه منصفة أم تتجاهل الظروف التي عمل فيها. بودكاست الدويتو يقدمه حذيفة وجيزاوي See omnystudio.com/listener for privacy information.','https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/15d3151c-9037-44f9-928b-b50700ecbfed/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201',4446,'2026-11-19T14:31:36Z'::timestamptz,0 FROM podcasts p WHERE p.title='الدويتو' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/15d3151c-9037-44f9-928b-b50700ecbfed/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'من تحت عجلات شاحنة مساعدات إلى بطولة العالم.. قصة دراج فلسطيني نجا من الإبادة! | بودكاست الدويتو','كيف بدأت رحلة مهدي رأفت مع كرة القدم؟ وما الذي دفعه للخروج بحثا عن الطعام لعائلته؟ وكيف تحوّلت لحظة مفاجئة إلى نقطة فاصلة غيّرت حياته بالكامل؟ وما الذي قاده من رحلة العلاج إلى المنافسة في البطولات الدولية؟ في هذه الحلقة من بودكاست الدويتو يستضيف جيزاوي وحذيفة الرياضي مهدي رأفت، عضو فريق طيور الشمس للدراجات، الذي يروي رحلته من طفولة ارتبطت بحلم كرة القدم إلى ظروف معيشية قاسية اضطرته لاتخاذ قرارات صعبة، وصولًا إلى تجربة غيّرت مسار حياته وفرضت عليه بداية جديدة. كما يتحدث عن رحلته العلاجية وانتقاله إلى مصر، وتحديات التأقلم مع الطرف الصناعي، وكيف ساعده انضمامه إلى فريق طيور الشمس على العودة إلى الرياضة والمشاركة في بطولات السعودية وتايلاند، ويشارك طموحاته المستقبلية ورسالته إلى ذوي الهمم حول مواجهة الصعوبات ومواصلة تحقيق الأحلام. بودكاست الدويتو يقدمه حذيفة وجيزاوي See omnystudio.com/listener for privacy information.','https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/23c5d71c-459d-4ba2-abe6-b50000e4bb17/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201',8482,'2026-11-12T14:15:31Z'::timestamptz,0 FROM podcasts p WHERE p.title='الدويتو' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/23c5d71c-459d-4ba2-abe6-b50000e4bb17/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'إقالة حسام حسن من منتخب مصر.. عملية اغتيال أم تدمير ذاتي؟ | بودكاست الدويتو','هل يُقال حسام حسن رغم إنجازه التاريخي مع منتخب مصر في كأس العالم؟ يناقش حذيفة وجيزاوي في هذه الحلقة من بودكاست الدويتو تسريبات إقالة مدرب المنتخب، والأسباب المحتملة وراءها، وما إذا كان القرار مرتبطًا بأدائه الفني أم بخلافات خارج الملعب. وتتناول الحلقة أزمة حسام حسن مع محمد صلاح بعد استبداله ومغادرته معسكر المنتخب، وزيارة هاني أبو ريدة إلى صلاح في طرابزون، إلى جانب خلافات المدرب السابقة مع أحمد حجازي ومحمد الشناوي ومصطفى محمد، وأزمته الأسرية التي أثارت جدلًا واسعًا. كما يناقشون دور اتحاد الكرة والإعلام في الأزمة، والبدائل المطروحة لخلافة حسام حسن، ومشكلات إدارة الكرة المصرية. وتطرح الحلقة تساؤلًا حول مستقبل المنتخب: هل يستمر البناء على إنجازه في كأس العالم، أم تعيده الصراعات إلى دوامة تغيير المدربين؟ بودكاست الدويتو يقدمه حذيفة وجيزاوي See omnystudio.com/listener for privacy information.','https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/5dedaf4c-64fd-4f2d-9a3b-b4fa010d689a/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201',3463,'2026-11-06T16:25:44Z'::timestamptz,0 FROM podcasts p WHERE p.title='الدويتو' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/5dedaf4c-64fd-4f2d-9a3b-b4fa010d689a/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201');
