SELECT p.id,'اعتزال ميسي.. النهاية التي فشل رونالدو في الحصول عليها | بودكاست الدويتو','هل حصل ميسي على الوداع الذي يستحقه مع منتخب الأرجنتين؟ ولماذا يواجه كريستيانو رونالدو نهاية مختلفة مع منتخب البرتغال؟ وهل كان قرار برشلونة بعدم استعادة ميسي هو الخيار الأفضل لمستقبل النادي؟ في هذه الحلقة من بودكاست الدويتو، يناقش جيزاوي وحذيفة نهاية رحلة ليونيل ميسي الدولية، وكيف تحوّل من لاعب واجه انتقادات جماهير الأرجنتين إلى رمز وطني يحظى بحبها وتقديرها. ويتوقفان عند التحول الكبير في شخصية ميسي منذ عام 2019، ودور المدرب ليونيل سكالوني في بناء منظومة متكاملة حوله، وكيف ساهم التفاف اللاعبين والجماهير في تحقيق إنجازاته التاريخية مع المنتخب. وفي المقابل، يناقشان أزمة كريستيانو رونالدو مع منتخب البرتغال، وتوتر علاقته بالمدرب خورخي خيسوس، والخلاف حول مشاركته ودوره داخل الفريق، وما إذا كان رونالدو يتحمل مسؤولية تأخر اعتزاله الدولي، أم أن الاتحاد البرتغالي فضّل المصالح التجارية على إدارة نهاية مسيرته بالشكل الذي يليق بتاريخه. كما يقارنان بين إرث النجمين وتأثير كل منهما في منتخب بلاده، ويتناولان رحيل ميسي عن برشلونة وخلافه مع خوان لابورتا، والأسباب التي جعلت عدم عودته إلى النادي قرارًا قد يخ','https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/25866802-d8eb-412f-b1ba-b4de012e732d/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201',4212,'2026-10-09T18:27:01Z'::timestamptz,0 FROM podcasts p WHERE p.title='الدويتو' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/25866802-d8eb-412f-b1ba-b4de012e732d/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201');
