SELECT p.id,'برشلونة في دوري الأبطال.. تفاصيل صغيرة تفصله عن اللقب المنشود | بودكاست الدويتو','هل يملك برشلونة ما يكفي للمنافسة على لقب دوري أبطال أوروبا رغم هشاشته الدفاعية؟ في هذه الحلقة من بودكاست الدويتو، يناقش حذيفة وجيزاوي جاهزية برشلونة انطلاقًا من تصريحات رودري، مرورًا بالقوة الهجومية وتطور خط الوسط، وصولًا إلى أزمة الدفاع والفارق بين جودة الأفراد والمنظومة التي تحميهم. ويستعرضا مقارنة برشلونة بأبرز منافسيه، خصوصًا أرسنال وباريس سان جيرمان، ودور خبرة لويس إنريكي، إلى جانب تأثير رودري داخل الملعب وتراكم خبرات الفريق بعد الخروج أمام إنتر وأتلتيكو مدريد. فهل تكفي قوة الهجوم وعمق دكة البدلاء لتعويض نقاط الضعف الدفاعية، أم يحتاج برشلونة إلى تدعيم جديد قبل أن يحلم بحصد اللقب؟ See omnystudio.com/listener for privacy information.','https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/697b8880-8d65-41ae-9db2-b4c901141cdd/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201',3611,'2026-09-18T16:56:09Z'::timestamptz,0 FROM podcasts p WHERE p.title='الدويتو' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/697b8880-8d65-41ae-9db2-b4c901141cdd/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201');
