SELECT p.id,'برشلونة الجديد.. النموذج الذي عجز الريال عن استنساخه | بودكاست الدويتو','هل ريال مدريد قادر على المنافسة فعلا؟ وهل برشلونة جاهز لبدء عصر جديد من الهيمنة؟ وهل معايير الكرة الذهبية تظلم بعض المرشحين؟ في هذه الحلقة من بودكاست الدويتو، يفكك جيزاوي وحذيفة أزمة ريال مدريد من جذورها، مستندين إلى تشخيص الصحفي جلين بلاك بأن النادي يملك نجومًا كبارًا، لكنه يفتقد المنظومة التي تحولهم إلى فريق تنافسي متكامل. كما يناقشان الصراع بين مبابي وفينيسيوس، ويقارنان الوضع الحالي بحقبة كريستيانو رونالدو، ويتوقفان عند خيارات إدارة ريال مدريد والصفقات التي كان يمكن أن تعالج بعض مشكلاته الفنية. وفي المقابل، يناقشان صعود برشلونة ونموذج الفريق المتكامل الذي يقوده هانزي فليك، وهل أصبح النادي الكتالوني أكثر جاهزية لمنافسة كبار أوروبا خلال السنوات المقبلة. كما يحللان المعايير الحقيقية للفوز بالكرة الذهبية، وما إذا كانت الأرقام والبطولات والأداء الفردي تكفي لحسم الجائزة، ومن الأحق بها بين هاري كين ورودري ولامين يامال وغيرهم. See omnystudio.com/listener for privacy information.','https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/93ca202e-018f-476f-a548-b4c101073a1b/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201',3271,'2026-09-10T16:31:39Z'::timestamptz,0 FROM podcasts p WHERE p.title='الدويتو' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/93ca202e-018f-476f-a548-b4c101073a1b/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'سجنت مرتين وفقدت النطق.. رواية عضو ألتراس سابق عن سنوات النار وحياة السجون | بودكاست الدويتو','كيف تحولت روابط الأولتراس من قوة جماهيرية في المدرجات إلى كيان مطارد؟ وماذا بقي اليوم من الوايت نايتس؟ في هذه الحلقة من بودكاست الدويتو، يجتمع حذيفة وجيزاوي مع العضو السابق بأولتراس وايت نايتس حاتم سيف في نقاش طويل وصريح حول تجربة الأولتراس من الداخل؛ من المدرج والتنظيم ومبادئ المجموعة، إلى ثورة يناير والاعتقالات والسجون والصدامات التي غيّرت مسار الحركة وجيلًا كاملًا من المشجعين. تتوقف الحلقة عند عقلية الأولتراس، والاستقلال المالي ومصادر التمويل، وعلاقته بالإعلام ووزارة الداخلية، والاتهامات التي لاحقت المجموعات بالعنف والتخريب. كما تستعيد محطات مفصلية من بورسعيد ومقتل عمرو حسين إلى مأساة الدفاع الجوي، وما تركته تلك الأحداث من أثر عميق في جمهور الكرة المصرية. ويروي حاتم تجربته مع السجن والأثر النفسي الذي بقي معه بعد الخروج، قبل أن ينتقل النقاش إلى سيد مشاغب والتحولات التي شهدتها وايت نايتس، والانقسام حول من حافظ على مبادئ الأولتراس ومن تخلى عنها، وحدود التنسيق مع الأمن وإدارة النادي، والسؤال الأوسع: هل ما زالت الفكرة موجودة أم لم يبق منها سوى الاسم؟ بودكاست الدويتو يقدمه حذيفة وجيزاوي S','https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/55374ccb-ece7-46b1-94df-b4b300ec45a0/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201',7065,'2026-08-28T14:05:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='الدويتو' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.omny.fm/d/clips/93ede1a5-f219-4562-a4af-b0c100d3da54/b3dab28d-3919-4aa2-b473-b0c100fc0e44/55374ccb-ece7-46b1-94df-b4b300ec45a0/audio.mp3?utm_source=Podcast&amp;in_playlist=824c3595-6171-4b83-95e5-b0c200923201');

