SELECT '0d408d45-5e30-5183-988e-5d467be1ec00'::uuid,'Sciware سايوير','بودكاست علمي عربي شهير يقدمه محمد قاسم، يبسط موضوعات العلوم والفضاء والتقنية والطبيعة بأسلوب شيق.','محمد قاسم','محمد قاسم مهندس ومقدّم بودكاست سايوير، أحد أشهر البودكاستات العلمية العربية في تبسيط العلوم والفضاء والتقنية.','0eacf812-edae-4159-9b9d-b91c71d6f3cb'::uuid,'scientific','https://mqasem.net/podcasts/newsciwarelogo.jpg','beginner',(SELECT id FROM hosts WHERE name_ar='محمد قاسم' LIMIT 1),0,0,NOW()
