INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'SW198 هل للحشرات مشاعر؟','هل لدى النحلة شعور؟ هل تشعر بالسعادة أو الحزن؟ هل للنحلة وعي لكي تشعر؟ لو قلت لك أن الإجابة على هذا السؤال أو سؤال ما إذا كانت النحلة أو الحشرات بشكل عام لها مشاعر هو ربما، قد ترفض الاعتقاد بأن هذا الشيء ممكن أو ربما قد تضحك: "الذبابة لها مشاعر؟"، من الصعب تخيل إمكانية أن تكون للحشرات مشاعر. في هذه الحلقة سأتناول الأسئلة من الناحية العلمية: هل تشعر الحشرة بالألم؟ هل تحزن أو تكتئب؟ أم أنها مجرد آلات تتحرك باستخدام جسد بيولوجي بسيط؟ هل الخلايا العصبية التي فيها ليست إلا أجهزة بسيطة تحركها لتفادي الخطر من شعور غير داخلي؟','https://traffic.libsyn.com/forcedn/mqasem/doinsectshavefeelings.mp3',1974,'2022-02-11T06:35:56Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/forcedn/mqasem/doinsectshavefeelings.mp3');
