SELECT p.id,'SW197 كيف يمكننا استيطان كامل المجرة؟','هل استيطان المجرة أمر ممكن؟ ماذا تقول الفيزياء في ذلك؟ وهل تسمح بتكوين امبراطورية مركزية فيه؟ أبدأ بسرد قصة تخيلية عن 10,000 في المستقبل، من خلالها أبين كيف يمكن للجيش التركيبي أخذ الكواكب كوكبا كوكبا في المجرة. ثم أنتقل إلى الفيزياء وما تقول في إمكانية القيام بذلك.','https://traffic.libsyn.com/secure/mqasem/colonizingthegalaxy.mp3',2634,'2021-11-06T11:39:21Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/colonizingthegalaxy.mp3');
