SELECT p.id,'SW196 تبريد الذرات باستخدام الليزر مقابلة مع سمية المدخلي','سمية المدخلي صنعت جهازا ثوريا لتبريد الذرات، ميزة الجهاز صغر حجمه، وخفة وزنه، وأجزاء منه مطبوعة باستخدام طابعة ثلاثية الأبعاد، سيصبح هذا الجهاز المحمول الأول من نوعه في عالم ميكانيكا الكم، وسيصبح كجهاز الآردوينو المفتوح المصدر، وستتمكن الجامعات من صناعته للتدريس والتدريب وللبحث العلمي.','https://traffic.libsyn.com/secure/mqasem/somayamadkhaly.mp3',2226,'2021-08-20T10:39:17Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/somayamadkhaly.mp3');
