SELECT p.id,'SW195 جهز نفسك لسياحة الفضاء','نحن الآن على أعتاب السفر السياحي إلى الفضاء، وقد يبدأ مع الأغنياء أولا، لغلاء سعر التذكرة، ولكن مع الوقت ومع تأسيس شركات متعددة للسفر إلى الفضاء ستنخفض الأسعار وسيكون في متناول الجميع، سيستمتع الجميع بهذه الرحلات، وبالنظر إلى الكون الواسع وإلى الأرض المعلقة بداخله.','https://traffic.libsyn.com/secure/mqasem/spacetourism.mp3',1670,'2021-07-08T05:34:43Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/spacetourism.mp3');
