SELECT p.id,'SW194 الكذبة الكبرى','هذه قصة العالم أندرو ويكفيلد وفرضية أن تطعيم فيروس الحصبة تصيب الأطفال بالتوحد، نشر الفكرة رغم عدم وجود دليل عليها، ورغم أنه نشر أبحاثا مزيفة، ولا تزال هذه الفكرة المزيفة معنا إلى يومنا هذا، فكرته لم تقف عند بل شوهت جميع أنواع التطعيمات. هذه هي قصته.','https://traffic.libsyn.com/secure/mqasem/thebiglie.mp3',3735,'2021-06-23T11:50:08Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/thebiglie.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'SW193 أزمتان فيزيائيتان هائلتان','أزمتان فيزيائيتان إحدهما عن سرعة اتساع الكون، والأخرى في ميكانيكا الكم، الفيزيائيون لا يعرفون الإجابة لهما. حاول العلماء منذ العشرينيات أن يضبطوا نتائج سرعة اتساع الكون، وإلى يومنا لم يجدوا إجابة تتفق مع أخرى، أي السرعات صحيحة؟ هل نحتاج إلى طرق جديدة للكشف عنها؟ أما في عالم ميكانيكا الكم، فقد أجرى العلماء تجربة جديدة حطمت حسابات الفيزيائيين، فإما أن تكون التجربة خاطئة، وهذا أمر مستبعد نوعا ما، خصوصا أنها جربت مرتين، أو الحسابات الفيزيائية خاطئة، أو قد تكون هناك جسيمات جديدة تضاف للمنوذج المعياري أو قوى جديدة لم يعرف عنها العلماء سابقا.','https://traffic.libsyn.com/secure/mqasem/Crisis_in_Physics.mp3',2059,'2021-05-23T06:11:54Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/Crisis_in_Physics.mp3');
