SELECT p.id,'SW189 التجربة العلمية الكويتية إلى المحطة الفضائية الدولية','مقابلة مع الدكتور بسام الفيلي عن إرسال تجربة كويتية إلى المحطة الفضائية الدولية، وكيف تقوم بنفس الشيء في بلدك. هدف التجربة إحياء روح العلم حب الفضاء في العالم العربي.','https://traffic.libsyn.com/secure/mqasem/KuwaitExperimentISS.mp3',3240,'2020-12-20T19:04:15Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/KuwaitExperimentISS.mp3');
