SELECT p.id,'SW188 الذكاء الاصطناعي يحل مشكلة دامت 50 عاما من غير حل','استخدمت جوجل الذكاء الاصطناعي لطوي البروتينات، مشكلة عويصة جدا دامت 50 عاما من غير حل. لو حاول الكمبيوتر محاكاة طوي البروتينات بالشكل الصحيح لاحتاج إلى مدة من الزمن أطول من عمر الكون بكثير لحلها، بينما البروتين يطوي نفسه في جزء من الثانية.','https://traffic.libsyn.com/secure/mqasem/Protein_Folding.mp3',1595,'2020-12-10T19:27:08Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/Protein_Folding.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'SW187 هل يجب علينا أن نخاف من لقاح الكورونا؟','مقابلة مع الدكتور إسلام حسين عن أنواع اللقاحات التي تعمل عليها العديد من الشركات حاليا من حول العالم، أسأله عن أنواع اللقحات، وإن كانت تختلف عن لقاح الإنفلونزا، وكذلك نتطرق لمزايا وعيوب كل نوع من أنواع اللقحات. مقابلة تعطي غير المختص في اللقحات فكرة عما يحدث في عالم المنتجين لها، وبإمكان الشخص المتخذ لقرار اختيار اللقاح للدولة أن يقرر أي اللقاحات يختار.','https://traffic.libsyn.com/secure/mqasem/shouldwebeafraidofvacc.mp3',5068,'2020-11-08T15:30:14Z'::timestamptz,0 FROM podcasts p WHERE p.title='Sciware سايوير' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://traffic.libsyn.com/secure/mqasem/shouldwebeafraidofvacc.mp3');

