SELECT 'b95165a9-791a-50fa-ae1c-e4368b34cf08'::uuid,'Dirham | درهم','بودكاست عربي يهتم بالمال والأعمال والاستثمار وتطوير المهارات المهنية، يقدمه أحمد بن موسى.','أحمد بن موسى','أحمد بن موسى مقدم بودكاست درهم، يناقش المال والأعمال والاستثمار والمهارات المهنية بطرح عملي.','6899eda0-adcf-486e-8040-4bd95f55f249'::uuid,'professional','https://files.cohostpodcasting.com/quill-file-prod/cc50e981-a2fc-4193-ba07-1ffa9b51df9c/shows/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/cover-art/original_469838b7b6597410ff03fb18d99251a2.jpg','beginner',(SELECT id FROM hosts WHERE name_ar='أحمد بن موسى' LIMIT 1),0,0,NOW()
