INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل يولد البائع الناجح أم يُصنع؟ (الجزء الثاني) | بودكاست درهم','في الجزء الثاني من الحلقة 11، والحلقة الأخيرة من الموسم الثالث لبودكاست درهم، يكمل أحمد بن موسى حديثه مع الأستاذ مصطفى الدينالي، خبير المبيعات القادم من سيسكو وساب وديل وهواوي. نتحدث عن مراحل العملية البيعية، وأسباب رفض الزبون الخمسة وكيف تتعامل مع كل منها، وفخ التخفيضات، وكيف تبني الثقة مع الزبون، وما الذي يجعل فريق المبيعات يبقى معك. إن فاتك الجزء الأول، ننصحك بمشاهدته أولاً. وشكراً لكل من رافقنا طوال الموسم الثالث. 🎧 متاح أيضاً على جميع منصات البودكاست.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/cba2cb7e-4b65-47c7-a62f-1d1cc8fd3e36/episode_b979ad1dc12edf52e7d2ae6478a81a7b.mp3',6072,'2026-11-20T15:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/cba2cb7e-4b65-47c7-a62f-1d1cc8fd3e36/episode_b979ad1dc12edf52e7d2ae6478a81a7b.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف يفكر البائع الناجح؟ (الجزء الأول) | بودكاست درهم','في الجزء الأول من الحلقة 11 من بودكاست درهم، يستضيف أحمد بن موسى الأستاذ مصطفى الدينالي، خبير المبيعات الذي قضى مسيرته المهنية في شركات عالمية مثل سيسكو وساب وديل وهواوي، ويدير اليوم شركة تدريب متخصصة في مهارات التواصل والمبيعات. نفتح في هذه الحلقة ملف المبيعات من أساسه: علاقة المبيعات بالتسويق، والفرق بين البيع للشركات والبيع للأفراد، ومن يتخذ قرار الشراء فعلاً داخل المؤسسات، وكيف تبني قائمة فرص تحميك من الأشهر الفارغة. ونتحدث عن البائع نفسه: هل يولد ناجحاً أم يُصنع، ولماذا يتعلم ماذا يسأل قبل أن يتعلم ماذا يقول، وكيف تحمي النزاهة سمعته على المدى الطويل. الجزء الثاني قريباً .','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/a7b3e0a9-3233-4645-9c3f-3a5ee7e038de/episode_cda9118e058aee090cdf12cf77b52cd2.mp3',5728,'2026-10-30T15:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/a7b3e0a9-3233-4645-9c3f-3a5ee7e038de/episode_cda9118e058aee090cdf12cf77b52cd2.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف يتحول لاعب كرة قدم إلى رجل أعمال؟ | بودكاست درهم','في الحلقة العاشرة من الموسم الثالث من بودكاست درهم، نستضيف الكابتن معتز بن عامر، قائد نادي الأهلي بنغازي ولاعب المنتخب الليبي سابقاً، والمؤسس والمدير التنفيذي لشركتي واما وراما العاملتين في قطاع تجزئة الملابس الرياضية في ليبيا وشرق أفريقيا. يروي الكابتن معتز رحلته من الملاعب إلى عالم الأعمال، بدءاً من متجر صغير ببنغازي عام 2007، مروراً بتوكيل أديداس في ليبيا وافتتاح أول فرع قبل الثورة بشهر، ووصولاً إلى نحو 20 فرعاً في ليبيا ورواندا وكينيا وأوغندا. ونتحدث معه عن تحوّل التجارة من متجر صغير إلى مؤسسة منظمة، وبناء الهيكل الإداري واستقطاب الخبرات، ومحاسبة كل فرع كأنه شركة مستقلة، وإدارة المخزون والتسعير والتسويق، والفرق بين السوق الليبية وأسواق شرق أفريقيا، والدروس التي تعلّمها من أخطائه.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/31c8971b-8fe0-4b9d-8a8d-e22c65a0c4a1/episode_80a537a2a024b9c2a2d6275c64a17d98.mp3',5999,'2026-10-09T16:34:11Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/31c8971b-8fe0-4b9d-8a8d-e22c65a0c4a1/episode_80a537a2a024b9c2a2d6275c64a17d98.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'بلد الحكايات، ملف السياحة في ليبيا | بودكاست درهم','ليبيا فيها أكاكوس وغدامس وشحات ولبدة، وفيها حكايات ميدوسا وحدائق الهيسبيريدس، ونبتة يُعتقد أنها أصل رمز القلب. فليش بلد فيه كل هذا ما عندهاش سياحة؟ ضيف هذه الحلقة طه الجواشي، مصور صحفي وصانع أفلام وثائقية وصانع محتوى، نُشرت أعماله في نيويورك تايمز والتايمز اللندنية. لكن قبل الكاميرا، كان مرشداً سياحياً في الصحراء الليبية، دخل القطاع سنة 2003 وقضى سنوات يرافق المجموعات من رأس الجدير إلى أكاكوس. في الحلقة نتكلم عن أول رحلة له في الصحراء وكيف غيّرت نظرته للحياة، وعن عبقرية عمارة غدامس، وعن واقع السياحة في ليبيا بين 2003 و2011، وعن تجربة إسبانيا اللي حوّلتها من العزلة والفقر إلى وجهة عالمية، وعن الاقتصاد الريعي وليش النفط والسياحة ما يتخلطوش، وعن السياحة الداخلية وقوة السرد في بناء الوجهات والعلامات التجارية.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/2f1215e2-7724-4501-888e-7872b927f280/episode_2f1ae0e0a738ce32b90bff54a489ae47.mp3',5722,'2026-09-25T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/2f1215e2-7724-4501-888e-7872b927f280/episode_2f1ae0e0a738ce32b90bff54a489ae47.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'من الخمس إلى طوكيو قصة شركة أسماك ليبيا | بودكاست درهم','من الخمس إلى طوكيو، قصة شركة أسماك ليبيا. ضيف هذه الحلقة الحاج محمد مفتاح العجيل، رئيس مجلس إدارة شركة أسماك ليبيا. حكى لنا بدايته من الخمس، وخروجه من الجيش سنة 1993 بلا راتب ولا خطة، وبدايته من أربعين ديناراً ومنها إلى التصدير لتونس ومالطا، والفاكس اللي فتح له السوق الياباني، لغاية افتتاح المصنع. وتحدثنا كذلك عن واقع قطاع الثروة السمكية في ليبيا والفرص الموجودة فيه.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/e4bee1ff-50a9-49fd-a224-3651c69bd2ce/episode_f969c6093406a51e1f369926f526c9cb.mp3',8747,'2026-09-11T11:01:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/e4bee1ff-50a9-49fd-a224-3651c69bd2ce/episode_f969c6093406a51e1f369926f526c9cb.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'قطاع التأمين في ليبيا : سوق بحجم 300 مليون دولار | بودكاست درهم','في هذه الحلقة من بودكاست درهم، نستضيف يحيى الباروني رئيس مجلس إدارة لشركة البركة للتأمين، ومؤسس أول شركة وساطة تأمين مرخصة في ليبيا. نتحدث عن بداياته في هذا القطاع، وكيف تُحسب المخاطر قبل أن تُكتب الوثيقة، ودور شركات إعادة التأمين العالمية، وتاريخ سوق التأمين الليبي منذ الستينيات وحتى اليوم. كما نفتح ملف سمعة شركات التأمين وأسباب شكاوى التأمين، وأزمة التأمين الصحي، والفرق بين التأمين التقليدي والتكافلي، وحجم السوق الليبي بالأرقام مقارنة بدول الجوار، إضافة إلى قصص حقيقية من داخل القطاع وفرص التمويل والتأمين الجديدة.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/5874a0f3-8788-4532-a653-3d2b9f9344e4/episode_9d14c6269e77826776fb8f83ef39e40e.mp3',7320,'2026-08-14T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/5874a0f3-8788-4532-a653-3d2b9f9344e4/episode_9d14c6269e77826776fb8f83ef39e40e.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل ليبيا مستعدة للحرب السيبرانية؟ | بودكاست درهم','في هذه الحلقة من بودكاست درهم، نستضيف المهندس زياد خليل، المؤسس والمدير التنفيذي لشركة الجذور الليبية لأمن المعلومات، أول شركة ليبية متكاملة في خدمات الأمن السيبراني. نتحدث عن بداياته في هذا المجال، ومعنى أن تكون مخترقاً أخلاقياً، وواقع الأمن السيبراني في ليبيا بالأرقام، وقصص اختراق حقيقية حدثت وكلفت أصحابها الكثير. كما نفتح ملف الاحتيال الرقمي وتسريب البيانات، ولماذا أصبح القطاع المصرفي الهدف الأول، ودور الذكاء الاصطناعي في الجيل القادم من الهجمات، إضافة إلى نصائح عملية للأفراد وأصحاب الشركات.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/92431414-410e-422a-81a9-d58818346b7a/episode_99aa5d233a4512b471d7d752ff069ffd.mp3',8185,'2026-07-31T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/92431414-410e-422a-81a9-d58818346b7a/episode_99aa5d233a4512b471d7d752ff069ffd.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف تحولت الأفكار إلى ملايين؟ | بودكاست درهم','كيف بدأت رحلة Geet Productions؟ وكيف تحولت من شغف بصناعة الأفلام إلى واحدة من أبرز شركات الإنتاج الإعلاني في ليبيا؟ في هذه الحلقة من بودكاست درهم، نستضيف عبدالرحمن غيث، المؤسس والمدير التنفيذي لشركة Geet Productions، للحديث عن رحلته في بناء الشركة، والتحديات التي واجهها في صناعة المحتوى والإعلانات، وكيف استطاع مع فريقه المساهمة في تغيير نظرة السوق للإنتاج المحلي. نتحدث في هذه الحلقة عن بداياته الأولى، وأهمية الجودة في بناء السمعة، وكواليس صناعة الإعلانات في ليبيا، وتطور سوق الإنتاج والإعلان، بالإضافة إلى التحديات التي تواجه الشركات الإبداعية، ومستقبل الذكاء الاصطناعي في هذا المجال. كما يشاركنا عبدالرحمن رؤيته حول إدارة المشاريع الإبداعية، وتسعير الأفكار، وبناء فرق العمل، والدروس التي تعلمها من سنوات طويلة من التجربة، وصولًا إلى حلمه الأكبر: صناعة فيلم ليبي طويل.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/656e0664-09d5-4a8c-8d8c-216477465c41/episode_f39c96b7e359c34deb66cd0b8f1f1c4b.mp3',5357,'2026-06-05T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/656e0664-09d5-4a8c-8d8c-216477465c41/episode_f39c96b7e359c34deb66cd0b8f1f1c4b.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'قطمير للتمور، من واحات ليبيا إلى الأسواق العالمية | بودكاست درهم','قطمير للتمور، من واحات ليبيا إلى الأسواق العالمية في هذه الحلقة من بودكاست درهم، يستضيف أحمد بن موسى الرئيس التنفيذي لشركة قطمير للتمور م.يحيى الشريف، للحديث عن رحلة بناء واحدة من أبرز شركات التمور في ليبيا. الحلقة تتناول تحديات الزراعة والتصدير، تطور سوق التمور الليبي، ومستقبل الصناعات التحويلية للتمور في ليبيا.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/fc6e495f-404c-4b89-abe6-d36d8cc97c15/episode_8d003200e95c523f5952b435ff02455b.mp3',8283,'2026-05-22T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/fc6e495f-404c-4b89-abe6-d36d8cc97c15/episode_8d003200e95c523f5952b435ff02455b.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'المنتجات التراثية, بين الموضة والسياحة | بودكاست درهم','من عالم النفط والاستثمار… إلى مشروع يعيد تقديم التراث الليبي بروح مختلفة 🇱🇾 في هذه الحلقة من بودكاست درهم، نستضيف لمياء بورويص، مؤسسة “حويتة”، للحديث عن رحلتها من الشركات العالمية إلى بناء مشروع قائم على الحرفة، الهوية، والمنتج الليبي. حلقة عن: التحول المهني، ريادة الأعمال، تحديات الحرف اليدوية، وكيف يمكن للهوية أن تتحول إلى قيمة حقيقية.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/03fcdb08-d2a4-41d6-b09d-d93f218f473a/episode_9fbd3a84b1a5f247ac612847e0b15433.mp3',6332,'2026-05-08T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/03fcdb08-d2a4-41d6-b09d-d93f218f473a/episode_9fbd3a84b1a5f247ac612847e0b15433.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'أسرار التجارة والشحن من الصين | بودكاست درهم','في هذه الحلقة الخاصة من بودكاست درهم نأخذكم إلى قلب مدينةقوانزو في الصين مع إدريس الصابر، بخبرة تمتد لأكثر من 20 سنة في عالم الشحن والتجارة بين ليبيا والصين. نفتح في هذا الحوار تفاصيل مهمة عن واقع الاستيراد، وكيف تبدأ رحلة البضائع من المصانع، وما الفرق بين شروط الشحن، وأهم الأخطاء التي يقع فيها التجار دون أن ينتبهوا. حلقة مليئة بالتجربة الواقعية والنصائح العملية لكل من يفكر في دخول مجال التجارة أو تطوير عمله.','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/a0c15500-375d-402a-9efe-579fd52f94e6/episode_d4eb83248aca475bf05128f2a2f3e454.mp3',6577,'2026-04-24T14:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/a0c15500-375d-402a-9efe-579fd52f94e6/episode_d4eb83248aca475bf05128f2a2f3e454.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'الجامعات الخاصة: تعليم متميز أم شهادات للبيع؟ | بودكاست درهم','في أول حلقة من الموسم الثالث من بودكاست درهم نناقش واقع التعليم العالي في ليبيا من منظور الجودة والكفاءة وقيمة التعليم كاستثمار حقيقي، من خلال استضافة د. محمد سعد، رئيس ومؤسس الجامعة الليبية الدولية، الذي يشارك تجربته في بناء نموذج تعليمي مختلف يركز على تطوير المهارات والمخرجات بدلًا من الكم. تتناول الحلقة التحديات التي تواجه القطاع، من الضغوط التنظيمية والاقتصادية إلى الصورة المجتمعية للتعليم الخاص، وتطرح سؤالًا محوريًا: هل الجامعات الخاصة تقدم قيمة حقيقية… أم مجرد شهادات؟','https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/55aabe5a-e4de-4453-a059-7e53165de0b7/episode_eb8c5dd2ecb954fe56c7743ff5c58e5c.mp3',7708,'2026-04-10T15:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='Dirham | درهم' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://audio.cohostcdn.com/show/cc54c6b4-e66a-4d83-92fb-68630a8ea7c6/episode/55aabe5a-e4de-4453-a059-7e53165de0b7/episode_eb8c5dd2ecb954fe56c7743ff5c58e5c.mp3');

