SELECT p.id,'حاتم دويدار في «كلام بزنس».. رجل الاتصالات بالمنطقة لماذا غادر بقمة النجاح؟','في عالم الأعمال، تُقاس قصص النجاح غالباً بحجم الإنجازات والأرباح، لكن القليل من القادة يختارون أن يُكتب الفصل الأخير من مسيرتهم المهنية بإرادتهم، وهم في قمة النجاح. هذا ما فعله حاتم دويدار، الذي قاد واحدة من أكبر عمليات التحول في قطاع الاتصالات بالمنطقة، محولاً «اتصالات» إلى مجموعة التكنولوجيا العالمية e&، عبر سلسلة من الاستحواذات والتوسعات الاستراتيجية التي أعادت رسم ملامح الشركة والقطاع.','https://api.spreaker.com/download/episode/73153196/hatem_eps_1.mp3',4996,'2026-07-24T17:23:33Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست CNN الاقتصادية' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://api.spreaker.com/download/episode/73153196/hatem_eps_1.mp3');
