INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'زياد بهاء الدين: انتهاء برنامج صندوق النقد بداية الاختبار الحقيقي.. والاستثمار مفتاح الأزمة','تقترب نهاية برنامج مصر مع صندوق النقد الدولي بنهاية هذا العام، ويرى الدكتور زياد بهاء الدين، نائب رئيس الوزراء المصري الأسبق، أن مصر لا تقف أمام نهاية مرحلة، بل أمام بداية اختبار أكثر صعوبة، مؤكداً أن انتهاء البرنامج لا يعني انتهاء الإصلاح، وإنما يفرض على الدولة وضع رؤية اقتصادية جديدة تنطلق من أولوياتها الوطنية.','https://api.spreaker.com/download/episode/72937389/773305fb_2791_44fe_a4e2_2b53de1e079f.mp3',3650,'2026-07-12T17:00:04Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست CNN الاقتصادية' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://api.spreaker.com/download/episode/72937389/773305fb_2791_44fe_a4e2_2b53de1e079f.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'حسين فريجة في كلام بزنس','لم تكن رحلة حسين فريجة، المدير العام لـ«سناب شات» في الشرق الأوسط وشمال إفريقيا وآسيا والمحيط الهادئ، مجرد انتقال بين شركات تكنولوجيا عربية وعالمية، بل كانت رحلة عايش خلالها أهم محطات تطور الاقتصاد الرقمي في المنطقة. فمن شركة «مكتوب» التي فتحت الباب أمام المحتوى العربي على الإنترنت، إلى «ياهو» التي كانت يوماً عملاق الإنترنت قبل أن تخسر موقعها، وصولاً إلى «سناب شات» التي تخوض اليوم معركة الحفاظ على الابتكار في سوق شديد المنافسة، يختصر فريجة أكثر من عقدين من التحولات التي شهدها قطاع التكنولوجيا.','https://api.spreaker.com/download/episode/72916200/d48c2969_38ae_428c_91ed_a44ff758673f.mp3',4024,'2026-07-10T16:55:02Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست CNN الاقتصادية' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://api.spreaker.com/download/episode/72916200/d48c2969_38ae_428c_91ed_a44ff758673f.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'طلال أبو غزالة في «كلام بزنس».. 88 عاماً من النجاح لمؤسس أكبر إمبراطورية عربية للملكية الفكرية','يرى مؤسس ورئيس مجموعة طلال أبو غزالة الدولية، الدكتور طلال أبو غزالة، أن الثروة الحقيقية لا تُقاس بحجم الأصول أو العقارات، وإنما بما يملكه الإنسان من معرفة وأفكار، مؤكداً أن ما صنع مجموعته العالمية لم يكن النفط أو التجارة أو الصناعة، بل الاستثمار المبكر في اقتصاد المعرفة والملكية الفكرية، في وقت لم يكن معظم الناس في المنطقة العربية يعرفون معنى هذا المجال أصلاً في الستينيات. وخلال مقابلة مطوّلة مع برنامج «كلام بزنس»، استعرض أبو غزالة رحلة امتدت لأكثر من ثمانية عقود، بدأت بطفل فلسطيني هُجّر من يافا عام 1948، وانتهت ببناء واحدة من أكبر المؤسسات العربية العاملة في مجالات الملكية الفكرية والمحاسبة والاستشارات والتكنولوجيا، تمتلك أكثر من 140 شركة ونحو 100 مكتب حول العالم ويعمل بها قرابة ألفي موظف.','https://api.spreaker.com/download/episode/72705670/talal_abu_ghzala_final.mp3',7779,'2026-06-26T17:44:08Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست CNN الاقتصادية' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://api.spreaker.com/download/episode/72705670/talal_abu_ghzala_final.mp3');
