SELECT p.id,'من قلب صعيد مصر يخرج الحلم وتتحقق الثروة.. رحلة «سيمبلكس» نحو العالمية','من محافظة في صعيد مصر تُدعى قنا وبأقل الإمكانات، بدأت رحلة أحمد شعبان، مؤسس شركة سيمبلكس، وكانت ورشة صغيرة وإمكانات محدودة، قبل أن تتحول شركته إلى أحد أبرز مصنعي ماكينات التحكم الرقمي «سي إن سي» (CNC) في مصر، مع حضور متزايد في أسواق الشرق الأوسط وإفريقيا.','https://api.spreaker.com/download/episode/72278367/simplex.mp3',5313,'2026-06-01T17:00:02Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست CNN الاقتصادية' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://api.spreaker.com/download/episode/72278367/simplex.mp3');
