SELECT p.id,'فيصل طوقان: نريد تحويل التكنولوجيا المالية إلى تجربة تقرّب المستخدم من ماله','في سوق تتسارع فيه التحولات الرقمية، وتزداد فيه المنافسة بين البنوك والشركات الناشئة والمنصات الإقليمية، تظهر زينة كواحدة من التجارب الإماراتية اللافتة في قطاع التكنولوجيا المالية.','https://api.spreaker.com/download/episode/72041016/ali_interview_14_may_2.mp3',1317,'2026-05-17T13:14:20Z'::timestamptz,0 FROM podcasts p WHERE p.title='بودكاست CNN الاقتصادية' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://api.spreaker.com/download/episode/72041016/ali_interview_14_may_2.mp3');

