SELECT '89e6ac6c-4532-5884-843e-65de3b5a8ceb'::uuid,'أميال لأخبار الطيران','بودكاست عربي متخصص في أخبار الطيران والسفر وصناعة النقل الجوي، يقدمه محمد بازيد وراكان العبيد.','محمد بازيد وراكان العبيد','محمد بازيد وراكان العبيد يقدمان بودكاست أميال، المتخصص في أخبار الطيران والسفر وتجارب المسافرين.','f26712fa-c904-43be-9f2a-a3f0f4860dd6'::uuid,'cultural','https://d3t3ozftmdmh3i.cloudfront.net/staging/podcast_uploaded_nologo/41517752/41517752-1720610336672-8fd82e26b77ee.jpg','beginner',(SELECT id FROM hosts WHERE name_ar='محمد بازيد وراكان العبيد' LIMIT 1),0,0,NOW()
WHERE NOT EXISTS (SELECT 1 FROM podcasts WHERE title='أميال لأخبار الطيران');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف تسبب جهاز واحد في تعطيل الطيران الأمريكي بالكامل ؟ | بودكاست أميال','في هذه الحلقة من بودكاست أميال نناقش واحدة من أبرز أزمات الطيران في الولايات المتحدة، بعد خلل تقني أثناء تحديث أنظمة الاتصال أدى إلى توقف عمليات الإقلاع لساعات، وأعاد فتح النقاش حول قِدم البنية التحتية للمراقبة الجوية، نقص الكوادر، وصعوبة تحديث منظومة بهذا الحجم من دون التأثير على آلاف الرحلات. ونتوقف أيضًا عند ما حدث في مومباي، بعد قرارات نقل عدد من الناقلات الخليجية إلى المطار الجديد وارتفاع تكاليف التشغيل، وتأثير ذلك على شركات مثل الخطوط السعودية وطيران ناس والقطرية والعمانية والكويتية، إضافة إلى الجدل حول الخانات الزمنية التاريخية وسبب استثناء بعض الناقلات من هذه الإجراءات. ومن أوروبا نناقش استحواذ مجموعة لوفتهانزا على الخطوط البرتغالية، وما إذا كانت استراتيجية الاستحواذات تساعد المجموعة على النمو أم تزيد من تعقيدها الإداري، كما نمر على افتتاح مطار رينيه معوض في شمال لبنان وعودة الحركة التجارية إليه، ودور القطاع الخاص في تشغيل المطار وشركة الطيران الجديدة المرتبطة به. ونتحدث كذلك عن الخطوط الكينية ومحاولتها إعادة طائرات متوقفة إلى الخدمة، وتوسع طيران الرياض في لندن، والرحلات الطويل','https://anchor.fm/s/f80fa660/podcast/play/129856343/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-21%2F9dc640ba-afb2-f6a4-2405-ed39cef3555a.mp3',2733,'2026-11-22T03:09:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/129856343/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-21%2F9dc640ba-afb2-f6a4-2405-ed39cef3555a.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'أسئلة المتابعين: لماذا تأخر تحديث مقصورات الخطوط السعودية؟ | بودكاست أميال','في هذه الحلقة من بودكاست أميال نجيب عن مجموعة من أسئلة المتابعين حول أبرز ما يشغل جمهور الطيران اليوم، من أسعار التذاكر والمنافسة بين شركات الطيران، إلى توسع الناقلات وتحديث المقصورات وتجربة المسافر. نبدأ بسؤال يتكرر كثيرًا: لماذا تكون بعض الرحلات الداخلية أغلى من رحلات دولية بمسافات قريبة؟ ونناقش أثر العرض والطلب، وعدد المشغلين على الخط، وكيف يمكن لغياب المنافسة المباشرة أن يرفع الأسعار حتى لو كانت المسافة أقصر. ونتحدث أيضًا عن المنافسة بين الناقلات السعودية، وهل هناك توزيع للوجهات بينها، ولماذا لا نشاهد حتى الآن توسعًا أكبر إلى وجهات بعيدة مثل أستراليا والبرازيل. كما نناقش خطط الخطوط السعودية وطيران الرياض، وتأثير تأخر تسليم الطائرات على سرعة التوسع. ومن أبرز أسئلة الحلقة: لماذا تأخر تحديث مقصورات الخطوط السعودية؟ ولماذا تختلف تجربة السفر بين طائرة وأخرى؟ نتناول مشروع تحديث المقصورات، وما يتطلبه من وقت وتجهيزات، ولماذا لا يمكن تحديث كامل الأسطول دفعة واحدة دون التأثير على التشغيل والتوسع. كما نناقش تجربة طيران الإمارات في تطوير المقصورات وتقليل عدد المقاعد، وكيف يمكن للشركة أن تحقق إ','https://anchor.fm/s/f80fa660/podcast/play/129429302/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-14%2Fb74d6e06-c7b1-e94b-276d-48968685c6d6.mp3',2930,'2026-11-15T04:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/129429302/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-14%2Fb74d6e06-c7b1-e94b-276d-48968685c6d6.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف تخطط «رِحال» لتشغيل 50 طائرة شحن في السعودية والخليج؟ | بودكاست أميال','هل يمكن لطائرات شحن صغيرة أن تغيّر مستقبل الشحن الجوي في السعودية؟ وكيف يمكن لشركة ناشئة أن تبني شبكة شحن جوي دون امتلاك طائراتها؟ في هذه الحلقة من بودكاست أميال، نستضيف طلحة الشنقيطي، مؤسس شركة «رِحال» ، للحديث عن نموذج جديد للشحن الجوي يعتمد على الطائرات الصغيرة لنقل الشحنات العاجلة والحساسة بين مدن المملكة ودول الخليج خلال ساعات بدلًا من أيام. نتعرف على قصة تأسيس «رحال»، وكيف اكتشف مؤسسوها فجوة في سوق الشحن الجوي، دفعتهم إلى زيارة 16 مطارًا سعوديًا لدراسة إمكانية تشغيل هذا النموذج، وما واجهوه من تحديات في إقناع المستثمرين والدخول إلى قطاع يتطلب استثمارات ضخمة. ونناقش أسباب اختيار طائرات سيسنا كرفان، وكيف يمكن استخدامها لنقل الأدوية والأعضاء البشرية وقطع غيار الطائرات، ولماذا قد تصل تكلفة نقل شحنة عاجلة إلى 300 ألف دولار. كما نتحدث عن طموح «رحال» لتشغيل 50 طائرة شحن خلال خمس سنوات، وخططها للتوسع في السعودية والخليج، والفرص التي تتيحها الطائرات الصغيرة لتطوير قطاع الشحن الجوي والخدمات اللوجستية. حلقة عن ريادة الأعمال في قطاع الطيران، ومستقبل الشحن الجوي، وكيف يمكن لفكرة مختلفة أن تفتح','https://anchor.fm/s/f80fa660/podcast/play/129024297/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-8%2Fae321b17-a142-304e-d06d-44383fa7bc88.mp3',4365,'2026-11-08T04:20:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/129024297/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-10-8%2Fae321b17-a142-304e-d06d-44383fa7bc88.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'بعد سنوات من التعثر: هل استعادت بوينغ ثقة السوق؟ | بودكاست أميال','في هذه الحلقة من بودكاست أميال نناقش عددًا من أبرز تطورات قطاع الطيران، ونبدأ من بوينغ التي تحاول استعادة زخمها بعد سنوات من التعثر والتأجيلات. نتحدث عن 737 MAX 10، وعن نتائج الشركة الأخيرة، ولماذا ما زال السوق مترددًا رغم التحسن الكبير في أرقام بوينغ، وما إذا كانت المشكلة اليوم في جودة الطائرات نفسها أم في قدرة الشركة على العودة إلى مستويات الإنتاج والتسليم التي كانت تحققها سابقًا. كما نتوقف عند واحدة من أطول الرحلات التجارية المجدولة بطائرة من عائلة A321، في رحلة تمتد إلى نحو 11 ساعة بين مومباي وأمستردام، ونناقش مدى جدوى تشغيل طائرة ضيقة البدن على رحلات بهذا الطول، وكيف تؤثر الحمولة وعدد المقاعد وتصميم المقصورة على تجربة المسافر وكفاءة التشغيل. وننتقل بعدها إلى تحديث مهم يخص المسافرين السعوديين إلى الولايات المتحدة، بعد اعتماد حاملي الجواز السعودي ضمن برنامج المسافر الموثوق، وما يعنيه ذلك من إجراءات أسرع عند الوصول والمغادرة، واستخدام مسارات وخدمات ذاتية مختصرة مقارنة بالإجراءات التقليدية. كما نشرح الفرق بين هذا البرنامج وخدمات التخليص المسبق الموجودة في بعض المطارات، ومن هم المسافرو','https://anchor.fm/s/f80fa660/podcast/play/128520324/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-31%2F885fa5fc-d21b-0ef8-d34b-de4ebceb2c77.mp3',3027,'2026-11-01T03:05:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/128520324/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-31%2F885fa5fc-d21b-0ef8-d34b-de4ebceb2c77.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل تتفوق طيران ناس على الخطوط التركية في سوريا؟ | بودكاست أميال','هل بدأت طيران ناس بمنافسة الخطوط التركية على السوق السوري؟ وهل نشهد منافسة جديدة بين الخطوط السعودية وطيران الرياض على الوجهات الدولية؟ ✈️ في حلقة جديدة من بودكاست أميال، نناقش التوسع الكبير لطيران ناس في سوريا، وارتفاع عدد رحلاتها بين السعودية والمدن السورية، وكيف استطاعت تعزيز حصتها السوقية أمام الناقلات الأخرى، وعلى رأسها الخطوط التركية. ونتحدث عن مستقبل طيران ناس سوريا، والفرص التي قد تفتحها الشركة لربط المدن السورية بالوجهات الأوروبية. ونتوقف عند التوسع المتسارع للخطوط السعودية في بريطانيا، خصوصًا في مانشستر، بالتزامن مع دخول طيران الرياض إلى السوق البريطاني. فهل تعكس هذه الخطوات نمو الطلب على السفر، أم أننا أمام منافسة مباشرة بين الناقلتين السعوديتين؟ كما نناقش المغادرة المفاجئة لأحد أبرز المسؤولين التنفيذيين في طيران الاتحاد، والتغييرات الكبيرة التي تشهدها شركة ساوث ويست الأمريكية، بعد تخليها عن بعض المميزات التي اشتهرت بها لسنوات، ودراستها دخول سوق الرحلات الدولية الطويلة بطائرات عريضة البدن لأول مرة في تاريخها. وفي الحلقة أيضًا، نجيب عن سؤال يشغل كثيرًا من المسافرين: هل تكفي 4','https://anchor.fm/s/f80fa660/podcast/play/128009309/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-24%2F473a2e63-d807-2db5-fb66-9877e4d911ed.mp3',2832,'2026-10-25T03:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/128009309/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-24%2F473a2e63-d807-2db5-fb66-9877e4d911ed.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'إيرباص أم بوينغ: من يفوز بصفقة الخطوط السعودية القادمة','هل تتجه الخطوط السعودية إلى صفقة طائرات جديدة مع إيرباص أم بوينغ؟ وما الذي يحدث عندما يتعطل أحد محركات الطائرة أثناء الرحلة؟ في حلقة جديدة من بودكاست أميال، نناقش الصفقة المرتقبة للخطوط السعودية لتحديث أسطولها من الطائرات عريضة البدن، والخيارات المطروحة أمامها، وكيف يمكن أن تؤثر هذه الصفقة على مستقبل علاقتها مع إيرباص وبوينغ. ونتوقف عند حادثة تعطل أحد محركات طائرة تابعة لطيران الإمارات خلال رحلتها من أستراليا إلى دبي، والتي اضطرت للعودة والهبوط بسلام. ونشرح كيف يتعامل الطيارون مع تعطل المحركات أثناء الطيران، ولماذا تقرر الطائرة العودة رغم قدرتها على التحليق بمحرك واحد. كما نناقش انتقادات بعض المسافرين لطريقة تعامل الخطوط القطرية مع الرحلات الملغاة خلال إغلاق بعض المطارات، وحقوق المسافرين في مثل هذه الظروف، ونتعرف على التحديث الجديد الذي قدمته بوينغ لكمبيوتر طائرات 737 ماكس باستخدام شاشات اللمس، ومدى ملاءمة هذه التقنية لقمرة القيادة. وفي الحلقة أيضًا، نستعرض نتائج شركة دلتا الأمريكية وتأثير ارتفاع أسعار الوقود على أرباحها، ونتعرف على أكبر خمس شركات لتأجير الطائرات في العالم، والتي تمتلك','https://anchor.fm/s/f80fa660/podcast/play/127661616/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-18%2Fca8fb24c-6085-61d5-6ac8-d8451e4c2a2f.mp3',3018,'2026-10-18T12:22:02Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/127661616/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-18%2Fca8fb24c-6085-61d5-6ac8-d8451e4c2a2f.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل تختفي أبراج المراقبة الجوية من المطارات؟','تشتعل المنافسة بين الخطوط السعودية وطيران الرياض على الوجهات الدولية، فبعد إعلان طيران الرياض عن تشغيل رحلات إلى مانشستر، رفعت الخطوط السعودية عدد رحلاتها إلى 10 رحلات أسبوعيًا. فهل بدأت المنافسة الحقيقية بين الناقلتين؟ ومن المستفيد من هذا التوسع؟ في هذه الحلقة من بودكاست أميال ، نناقش أبرز مستجدات قطاع الطيران، ونبدأ بالمنافسة بين الخطوط السعودية وطيران الرياض، واستراتيجية كل ناقلة في التوسع وحماية حصتها السوقية، والوجهات الجديدة المنتظرة لطيران الرياض. وننتقل إلى أستراليا للحديث عن مطار غرب سيدني الجديد، الذي سيعمل على مدار الساعة ويعتمد على تقنيات المراقبة الجوية عن بُعد، ونتساءل: هل نشهد مستقبلًا مطارات بلا مراقبين داخل أبراج المراقبة؟ كما نتناول صفقة طيران الرياض لإنشاء مركز متخصص في حسابات حمولة الطائرات، وما تكشفه عن المنافسة في سوق الخدمات الأرضية، إلى جانب تطورات السوق الأمريكي بعد أزمة شركة سبيريت، والمنافسة على حقوق الإقلاع والهبوط في المطارات. ونناقش أيضًا أبرز التطورات التقنية والتشغيلية في صناعة الطيران، من المنافسة بين شركات الاتصال الجوي إلى كواليس تجهيز الطائرات بين ال','https://anchor.fm/s/f80fa660/podcast/play/127661550/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-18%2Fba3d2f7e-d0b8-c17e-00c8-d2832ea9e46b.mp3',3213,'2026-10-18T12:20:33Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/127661550/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-18%2Fba3d2f7e-d0b8-c17e-00c8-d2832ea9e46b.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل تنهي إيرباص A350F هيمنة بوينغ على سوق طائرات الشحن','هل تنجح إيرباص في كسر سيطرة بوينغ على سوق طائرات الشحن؟ في حلقة جديدة من بودكاست أميال، نناقش دخول إيرباص المنافسة بطائرتها الجديدة A350F المخصصة للشحن، وما الذي يميزها عن طائرات بوينغ، وكيف يمكن أن تؤثر في مستقبل سوق الشحن الجوي. ونتوقف عند الخلل المكتشف في أنظمة طائرات بوينغ 737 ماكس، وأسباب تحفظ بعض شركات الطيران الأمريكية على استلام الطائرات بالتحديث الجديد. كما نتناول توسع خطوط ألاسكا بعد استحواذها على خطوط هاواي، وخططها لمنافسة شركات الطيران الأمريكية الكبرى، ونناقش مستقبل طائرة إيرباص A380، ولماذا تتمسك بها طيران الإمارات بينما لا يزال مستقبلها غير واضح لدى الخطوط القطرية. وفي الحلقة أيضًا، نتحدث عن التسعير الديناميكي لتذاكر الطيران، وكيف يمكن أن يختلف سعر رحلتين للوجهة نفسها وفي اليوم نفسه من 15 إلى 480 جنيهًا إسترلينيًا، ونستعرض أقدم خمس شركات طيران لا تزال تعمل حتى اليوم. #بودكاست_أميال #إذاعة_مختلف #الطيران #إيرباص #بوينغ','https://anchor.fm/s/f80fa660/podcast/play/126766550/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-3%2Ffab48bf3-cf1e-10ab-7767-48dcd31cf021.mp3',3208,'2026-10-04T03:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/126766550/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-3%2Ffab48bf3-cf1e-10ab-7767-48dcd31cf021.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'ماذا حدث لطائرة فلاي دبي قبل هبوطها في تبوك؟','في هذه الحلقة الخاصة من بودكاست أميال، نناقش حادثة طائرة فلاي دبي من طراز بوينغ 737 ماكس 8، التي تعرضت لهبوط حاد ومفاجئ أثناء رحلتها، قبل أن تهبط اضطراريًا في مطار تبوك. كيف يمكن لطائرة أن تفقد آلاف الأقدام من ارتفاعها خلال ثوانٍ؟ وما المخاطر التي تتعرض لها الطائرة عند الانحدار بهذه السرعة؟ وكيف يتعامل الطيارون مع مثل هذه الحالات لاستعادة السيطرة عليها؟ نتناول مع الكابتن راكان الجانب الفني للحادثة، ونناقش الفرق بين فلسفة بوينغ وإيرباص في أنظمة التحكم والحماية، وحدود تدخل الكمبيوتر في قرارات الطيار، ومدى قدرة الطائرة على تحمل السرعات والضغوط الاستثنائية. كما نناقش الروايات المتداولة حول هوية الشخص الذي أعاد السيطرة على الطائرة، وإمكانية أن يتمكن شخص غير مؤهل للطيران من التعامل مع موقف بهذه الخطورة، إلى جانب أسباب وجود طيارين إضافيين على متن بعض الرحلات. وننتقل إلى طريقة تعامل الجهات السعودية والإماراتية مع الحادثة، والبيانات الرسمية التي صدرت عقب الهبوط، وتوزيع المسؤوليات بين الجهات المختصة بالتحقيقات الفنية والأمنية والجنائية، ودور مركز سلامة النقل السعودي في التحقيق الفني. ونتطرق أيضً','https://anchor.fm/s/f80fa660/podcast/play/126740085/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-3%2Fc5c05ddb-de77-e17c-bbb2-18caaf8c6f33.mp3',2455,'2026-10-03T12:39:03Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/126740085/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-3%2Fc5c05ddb-de77-e17c-bbb2-18caaf8c6f33.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كيف غيّر مطار إسطنبول موازين الطيران العالمي','في هذه الحلقة من بودكاست أميال، نناقش دخول فلاي دبي إلى سوق الشحن الجوي، بعد إطلاق ذراع مخصصة للشحن والاستعانة بثلاث طائرات لنقل البضائع. ما الذي يدفع شركة عُرفت برحلات الركاب إلى هذا التوسع؟ وهل تستطيع منافسة الشركات الكبرى في المنطقة؟ وما الفرص التي يفتحها نمو التجارة الإلكترونية وحركة الشحن بين الأسواق؟ وننتقل إلى مطار إسطنبول الذي يواصل توسعه بافتتاح مدرج جديد بتكلفة تقارب مليار دولار. نتحدث عن أهمية هذا الاستثمار، وكيف يمكن لمدرج إضافي أن يرفع كفاءة المطار، ويقلل أوقات انتظار الطائرات وحركتها على الأرض، وما الذي تعنيه هذه التوسعات في ظل المنافسة بين المطارات العملاقة في إسطنبول ودبي والرياض. كما نستعرض تقدّم مطار الرياض على الدوحة في تصنيف الربط الجوي، ونناقش المعايير التي تحدد قوة المطار: هل هي أعداد الرحلات، أم تنوع الوجهات وشركات الطيران، أم سهولة الربط بين الرحلات؟ ونتوقف عند تصريحات الخطوط القطرية بشأن ارتفاع تكاليف الوقود، وكيف تتعامل الشركة مع هذه الضغوط دون اللجوء مباشرة إلى زيادة أسعار التذاكر، إلى جانب إعادة هيكلة الطيران العماني، ومستجدات رحلات الخطوط السعودية ومصر للطي','https://anchor.fm/s/f80fa660/podcast/play/126343479/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-26%2F438afb2a-129b-574f-abce-a81b9debaf21.mp3',3175,'2026-09-27T03:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/126343479/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-26%2F438afb2a-129b-574f-abce-a81b9debaf21.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'ناقل جديد يدخل السوق السعودي: هل تغيّر العربية للطيران أسعار الرحلات','في هذه الحلقة من بودكاست أميال نبدأ مع انطلاق ناقل سعودي جديد من الدمام، العربية للطيران ، التي تبدأ عملياتها بأسعار منافسة تصل في بعض العروض إلى 99 ريالًا. نناقش لماذا اختارت الدمام نقطة انطلاق، وما الفرص التي لم تستغلها شركات الطيران السعودية سابقًا في المنطقة الشرقية، خصوصًا في أسواق الهند وباكستان، وهل دخول منافس جديد قد يشعل المنافسة مع طيران ناس وأديل ويضغط على أسعار التذاكر. ثم ننتقل إلى واحدة من أكبر شركات الطيران الاقتصادي في آسيا، إير آسيا ، وسط ضغوط مالية وتساؤلات حول قدرتها على الاستمرار. الشركة تسيطر على جزء كبير من السوق المحلي الماليزي، لكنها تواجه التزامات مالية ضخمة وتبحث عن تمويل جديد. فكيف وصلت واحدة من أشهر قصص نجاح الطيران الاقتصادي إلى هذه المرحلة؟ وماذا سيحدث للسوق إذا تعثرت؟ ونناقش أيضًا نتائج جوائز سكاي تراكس وأفضل شركات الطيران عالميًا، وتقدم الخطوط السعودية في التصنيف وحصولها على جوائز مرتبطة بطواقمها، بالإضافة إلى موقع القطرية والإمارات والتركية وغيرها. ونطرح السؤال الأهم: إلى أي درجة يمكن الاعتماد على هذه التصنيفات؟ ولماذا تهتم شركات الطيران بها إلى هذا الح','https://anchor.fm/s/f80fa660/podcast/play/126004529/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-19%2Ff22625ef-9c91-929d-45a3-0e6d97d1343f.mp3',3829,'2026-09-20T03:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/126004529/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-19%2Ff22625ef-9c91-929d-45a3-0e6d97d1343f.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'هل تحتاج مكة إلى مطار جديد أم أن الحل موجود في الطائف','في هذه الحلقة من بودكاست أميال نبدأ من سؤال يتكرر كثيرًا: لماذا لا يوجد مطار في مكة؟ وهل نحتاج فعلًا إلى مطار جديد، أم أن تفعيل مطار الطائف وتوجيه جزء من الرحلات إليه قد يكون خيارًا أكثر جدوى؟ نناقش تأثير ذلك على رحلات العمرة، ومطار جدة، وشركات الطيران، وتجربة المسافر. ثم ننتقل إلى الصين، أحد أكبر أسواق الطيران في العالم، حيث تواصل شركات الطيران تسجيل الخسائر رغم ضخامة السوق، وارتفاع الطلب، وحداثة الأساطيل والمطارات. فما الذي يجعل قطاعًا بهذه الإمكانات يعاني ماليًا؟ وهل المشكلة في الوقود أم في طريقة إدارة وتشغيل السوق؟ ونتحدث أيضًا عن استعداد دلتا لبدء رحلاتها المباشرة إلى الرياض، والفرصة التي تراها في سوق ضخم يعتمد جزء كبير من مسافريه بين السعودية وأمريكا على رحلات الترانزيت، وما الذي قد يعنيه دخولها للمنافسة على هذا الخط. كما نناقش قصة لافتة مع الخطوط الكورية ، بعدما بادرت بالاعتذار وتعويض أحد المسافرين عن عطل في شاشة مقعده قبل أن يشتكي أصلًا، ومنها نفتح نقاشًا أوسع: هل لا تزال شاشات الطائرات مهمة للمسافر؟ ولماذا قررت أمريكان إيرلاينز العودة إليها بعد سنوات من إزالتها؟ وفي فقرة مصطلح','https://anchor.fm/s/f80fa660/podcast/play/125644579/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-12%2F46632dcb-159e-19c1-e21b-a39f40e48404.mp3',3482,'2026-09-13T03:00:00Z'::timestamptz,0 FROM podcasts p WHERE p.title='أميال لأخبار الطيران' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/f80fa660/podcast/play/125644579/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-12%2F46632dcb-159e-19c1-e21b-a39f40e48404.mp3');

